1	// Ubertest: the traceability spine between dev/requirements/requirements.md and the cases
2	// that verify it. The spec enumerates the requirement NUMBERS; the CASES declare,
3	// each for itself, how its leaf is verified (its `kind` / `tbd`). This gate is the
4	// strict bijection between them, plus the routing rules each kind implies:
5	//
6	//   - EVERY leaf has exactly one `<slug>.<id>.case.js` (the FILENAME is the link), and
7	//     every case names a real leaf. No leaf is unclaimed; no case is a stray.
8	//   - A case's `kind` (default "popup") decides verification:
9	//       * "popup" / "icon" — an image leaf, pinned by a `<slug>.<id>.png` snapshot
10	//         (rendered by render-snapshot.js, compared by popup-snapshots.test.js).
11	//       * "behavior"       — a click/navigation a static image can't observe, so it
12	//         carries NO image and is verified by dev/requirements/behavior/events-view-actions.test.js
13	//         (which self-asserts it covers exactly the kind:"behavior" cases). A PNG
14	//         "covering" a behavior is the #429 anti-pattern, so we forbid one here.
15	//   - A `tbd: true` case is an undecided edge case: it still renders (a provisional
16	//     snapshot under a "TO BE DECIDED" banner), so it needs no special handling here
17	//     beyond the bijection.
18	//
19	// A new leaf with no case fails here; a stray/misnamed case fails; a behavior case
20	// that smuggled in a PNG fails.
21	"use strict";
22	
23	const { test } = require("node:test");
24	const assert = require("node:assert/strict");
25	const fs = require("node:fs");
26	const { loadCases, leafIdOf, snapshotPath } = require("./shared/cases");
27	const { allRequirementIds, leafRequirementIds } = require("./shared/ui-requirements");
28	const { KIND_NAMES, IMAGE_KINDS } = require("./shared/kinds");
29	
30	const allIds = new Set(allRequirementIds());
31	const leaves = leafRequirementIds();
32	const cases = loadCases();
33	
34	// A case file is `<slug>.<leaf-id>.case.js`: a kebab-case component/feature slug,
35	// then the dotted requirement number it pins. The leaf id is the trailing run.
36	const PER_LEAF = /^[a-z][a-z0-9-]*\.(\d+(?:\.\d+)+)$/;
37	const idOf = (c) => leafIdOf(c.name);
38	const kindOf = (c) => c.kind;
39	// Kinds are auto-discovered from the <kind>/kind.js descriptors (shared/kinds.js),
40	// so this gate hardcodes no list — adding a kind folder extends it for free.
41	const KNOWN_KINDS = new Set(KIND_NAMES);
42	// The kinds with no rendered image — verified by a dedicated runner, not a snapshot.
43	const NON_IMAGE_KINDS = new Set(KIND_NAMES.filter((k) => !IMAGE_KINDS.includes(k)));
44	
45	test("dev/requirements/requirements.md yields leaf requirements", () => {
46	  assert.ok(allIds.size > 0, "no `N.M` requirement IDs parsed from dev/requirements/requirements.md");
