1	// UI snapshot tests — the single visual-comparison engine for every pixel-asserted
2	// requirement. Each per-leaf case supplies fake data; render-snapshot.js turns it
3	// into a PNG with the RIGHT renderer, chosen by the case's own `kind` (the popup's
4	// REAL render() by default; the real toolbar-icon worker in a fake browser for a
5	// `kind: "icon"` case — §10), and the
6	// result is compared pixel-by-pixel (via pixelmatch) against the committed
7	// reference PNG (dev/requirements/<kind>/cases/<name>.png). So the
8	// snapshots track the shipped code directly; there is no hand-maintained copy of
9	// the popup markup or the icon art. The comparison, naming, and refresh below are
10	// shared across both — only the pixel source differs. Run `npm run refresh:ui` to
11	// regenerate after an intentional change to the popup, the views, events-popup/popup.css, or
12	// the toolbar icon.
13	//
14	// A case is a self-contained scenario: its data lives only in the case file
15	// (never in production code, never in a shared gallery). See the testing-guide
16	// skill (.claudinite/local/packs/gcec/skills/testing-guide/SKILL.md).
17	"use strict";
18	
19	const { test } = require("node:test");
20	const assert = require("node:assert/strict");
21	const fs = require("node:fs");
22	const path = require("node:path");
23	const { PNG } = require("pngjs");
24	const pixelmatch = require("pixelmatch").default;
25	const { loadCases, snapshotPath } = require("../cases");
26	const { renderSnapshot, rendersImage } = require("./render-snapshot");
27	const { artifactPath } = require("../snapshot-artifacts-dir");
28	
29	// Rendering is deterministic (satori + resvg + bundled fonts, no browser), so a
30	// snapshot must match its reference EXACTLY — any differing pixel is a real,
31	// intentional-or-not change to the popup. If cross-platform rasterization noise
32	// ever makes this flap, revisit a small tolerance then rather than pre-emptively.
33	const MAX_DIFF_RATIO = 0;
34	
35	async function compareToSnapshot(testCase, pngBuffer) {
36	  const name = testCase.name;
37	  const snapPath = snapshotPath(testCase);
38	  const actualPath = artifactPath(`${name}.actual.png`);
39	  const diffPath = artifactPath(`${name}.diff.png`);
40	
41	  const actual = PNG.sync.read(pngBuffer);
42	  assert.ok(
43	    fs.existsSync(snapPath),
44	    `No stored snapshot at ${snapPath}; run "npm run refresh:ui" to create one.`
45	  );
46	  const expected = PNG.sync.read(fs.readFileSync(snapPath));
47	
48	  if (actual.width !== expected.width || actual.height !== expected.height) {
49	    fs.writeFileSync(actualPath, pngBuffer);
50	    assert.fail(
51	      `${name}: popup size changed: expected ${expected.width}x${expected.height}, got ` +
52	        `${actual.width}x${actual.height}. Run "npm run refresh:ui" if this is intentional.`
53	    );
54	  }
55	
56	  const { width, height } = actual;
57	  const diff = new PNG({ width, height });
58	  const diffPixels = pixelmatch(actual.data, expected.data, diff.data, width, height, { threshold: 0.1 });
59	  const ratio = diffPixels / (width * height);
60	
61	  if (ratio > MAX_DIFF_RATIO) {
62	    fs.writeFileSync(actualPath, pngBuffer);
63	    fs.writeFileSync(diffPath, PNG.sync.write(diff));
64	    assert.fail(
65	      `${name}: popup UI changed: ${diffPixels} of ${width * height} pixels differ ` +
66	        `(${(ratio * 100).toFixed(2)}%). See ${actualPath} and ${diffPath}, ` +
67	        `or run "npm run refresh:ui" if this is intentional.`
68	    );
69	  } else {
70	    for (const p of [actualPath, diffPath]) {
71	      if (fs.existsSync(p)) fs.unlinkSync(p);
72	    }
73	  }
74	}
75	
76	// Only the image-producing cases are snapshotted here (the popup + icon kinds); a
77	// non-image kind (behavior/extractor/logic) has no pixels and is verified by its
78	// own runner — e.g. dev/requirements/behavior/events-view-actions.test.js.
79	const CASES = loadCases().filter(rendersImage);
80	
81	test("there is at least one UI case", () => {
82	  assert.ok(CASES.length > 0, "no image-producing dev/requirements/{popup,icon}/cases/*.case.js found");
83	});
84	
85	// The popup's date/time copy comes from the real views' toLocale* calls, which
86	// follow the runtime's default locale. The committed PNGs are authored in en-US
87	// (Node's fallback when LANG is unset or C.UTF-8 — the CI/sandbox default). Guard
88	// it so a maintainer on a non-English shell gets an actionable message instead of
89	// a baffling text-only pixel diff.
90	test("the environment resolves to the en-US locale the snapshots assume", () => {
91	  const locale = new Intl.DateTimeFormat().resolvedOptions().locale;
92	  assert.equal(
93	    locale,
94	    "en-US",
95	    `UI snapshots are authored in en-US, but this environment resolves to "${locale}". ` +
96	      `Unset LANG/LC_ALL (or set LANG=C.UTF-8) when running/regenerating the UI snapshots.`
97	  );
98	});
99	
100	for (const testCase of CASES) {
101	  test(`UI case "${testCase.name}" (${testCase.description}) matches its snapshot`, async () => {
102	    await compareToSnapshot(testCase, await renderSnapshot(testCase));
103	  });
104	}
