1	/* Fringe Discover — front-end logic
2	 * - loads mock show data (all happening *today*, scoped to the next few hours)
3	 * - renders an interactive Leaflet map of Edinburgh venues
4	 * - renders the "Happening Now" list
5	 * - three interactive constraint filters:
6	 *     1. Genre      — multi-select of Fringe categories (filters map + list)
7	 *     2. Travel     — how you're getting to the next show
8	 *     3. Next show  — pick the exact start time, then the show, and pin it
9	 *
10	 * Loaded as an ES module (`<script type="module">` in index.html) so it can share
11	 * real code with the planner instead of copy-pasting it — see shared/geo.js.
12	 */
13	
14	import { isInUK } from "../shared/geo.js";
15	import { cachedFetchJson, DAY_MS } from "../shared/data-cache.js";
16	import { friendlyDuration } from "../shared/duration.js";
17	import { PRICE_OPTIONS, matchesPrice, priceLabel, showPrice } from "../shared/price.js";
18	import { geocodeUrl, parsePlaces, placeIcon, partnerLink, AFFILIATES } from "./places.js";
19	import {
20	  FESTIVAL_TZ,
21	  festivalDate,
22	  festivalNow,
23	  msToNextMinute,
24	  timeZoneLabel,
25	} from "./clock.js";
26	import {
27	  WHEEL_MINUTES,
28	  defaultConstraintTime,
29	  earliestWheelMinutes,
30	  minutesForHour,
31	  wheelHours,
32	} from "./constraint-time.js";
33	import { clockLabel, fringeMoment, hourLabel, realMoment } from "../shared/fringe-day.js";
34	
35	const EDINBURGH = [55.9486, -3.1881];
36	
37	/* Default "you are here" pin — central Edinburgh (Princes Street / Royal Mile
38	 * area) so the UI has a sensible starting point before / unless the user shares
39	 * their real location. */
40	const USER_DEFAULT = [55.9523946827963, -3.188258484671504];
41	
42	/* Google Maps logo (marks the "Open in Maps" link that opens Google Maps).
43	 * Inline SVG so it needs no network and inherits crisp scaling. */
44	const GMAPS_LOGO =
45	  '<svg class="gmaps-logo" viewBox="0 0 40 40" width="15" height="15" aria-hidden="true" focusable="false">' +
46	  '<defs><clipPath id="gmapsPin"><path d="M20 2C12.8 2 7 7.8 7 15c0 8.6 10.3 19.5 12.2 21.5.4.5 1.2.5 1.6 0C22.7 34.5 33 23.6 33 15 33 7.8 27.2 2 20 2z"/></clipPath></defs>' +
47	  '<g clip-path="url(#gmapsPin)">' +
48	  '<path fill="#4285F4" d="M20 15 L0 40 L0 0 Z"/>' +
49	  '<path fill="#EA4335" d="M20 15 L0 0 L40 0 Z"/>' +
50	  '<path fill="#FBBC04" d="M20 15 L40 0 L40 40 Z"/>' +
51	  '<path fill="#34A853" d="M20 15 L40 40 L0 40 Z"/>' +
52	  '</g><circle cx="20" cy="15" r="4.6" fill="#fff"/></svg>';
53	
54	/* The official-style Fringe genre categories. */
55	const GENRES = [
56	  "Cabaret and Variety",
57	  "Children's Shows",
58	  "Comedy",
59	  "Dance, Physical Theatre & Circus",
60	  "Events",
61	  "Exhibitions",
62	  "Music",
63	  "Musicals and Opera",
64	  "Spoken Word",
65	  "Theatre",
66	];
67	
68	/* How the user might travel between shows, and rough door-to-door speeds
69	 * (km/h) used to estimate travel time. (No bus mode — we can't give honest
70	 * schedules, so it would mislead more than help.) */
71	const TRAVEL_MODES = ["Walking", "Taxi/Car", "Bicycle"];
72	const TRAVEL_SPEEDS_KMH = {
73	  // Walking dialled down to ~2/3 of a brisk 5 km/h — Edinburgh's closes, hills,
74	  // stairs and festival crowds make real walking slower than the crow flies.
75	  Walking: (5 * 2) / 3,
76	  "Taxi/Car": 30,
77	  Bicycle: 15,
78	};
79	
80	/* Reachability window. The user picks how far they'll travel (in minutes) in
81	 * the travel card; DEFAULT_MAX_TRAVEL seeds it. The slider runs 1–60 min in
82	 * one-minute steps. A show that starts up to GRACE_MINUTES before you'd
83	 * actually arrive is still shown, but faded — you'd only just miss it. */
84	const DEFAULT_MAX_TRAVEL = 10;
85	const MIN_TRAVEL_MINUTES = 1;
86	const MAX_TRAVEL_MINUTES = 60;
87	const GRACE_MINUTES = 5;
88	
89	/* Price filter — real ticket amounts, shared with the planner so the two pages
90	 * offer the same money: "any", "free", then a ladder of inclusive caps
91	 * (shared/price.js). The day files carry each PERFORMANCE's cheapest band as
92	 * `pm` — a preview and a Saturday of the same show cost different money, and
93	 * this page only ever shows one night at a time. */
94	const PRICE_FILTERS = PRICE_OPTIONS.map((o) => o.value);
95	
96	/* ===== DEBUG: simulated "now" =====================================
97	 * The whole flow is scoped to "the next few hours today", so for testing we
98	 * pin a fixed clock instead of the real one. This is a testing pre-set exactly
99	 * like the pre-set location: a confirmed in-UK location replaces it with the
100	 * device's real clock (see requestUserLocation / adoptRealClock).
101	 *
102	 * Every field here is Edinburgh wall-clock — the same footing the show times
103	 * are on — so `minutes` can be compared against a show's start directly.
104	 *
105	 * `date` / `dateLabel` / `time` are the real calendar moment: what the header
106	 * shows and what a booking link needs. `fringeDate` and `minutes` are that same
107	 * moment expressed as a fringe day (shared/fringe-day.js), which runs 06:00 →
108	 * 06:00 — they name the day file to load and the position within it, so at
109	 * 00:30 they still point at last night's file with `minutes` past 1440.
110	 * Everything that compares against a show's start time uses `minutes`. */
111	const NOW = {
112	  date: "2026-08-14",       // real calendar date
113	  dateLabel: "Fri 14 Aug",
114	  time: "15:44",
115	  tz: "BST",                // British Summer Time
116	  fringeDate: "2026-08-14", // which day's data file to load (data/days/<date>.json)
117	  minutes: 15 * 60 + 44,    // minutes into the fringe day (>= 1440 after midnight)
118	};
119	
120	/* Backing Date for the simulated clock. The debug date/time picker reads and
121	 * writes this, and we project it onto NOW (which is used throughout the app).
122	 * The year is arbitrary — only the day/time matter to the demo. Built through
123	 * festivalDate so the pre-set is 15:44 *in Edinburgh* on any device. */
124	let simNowDate = festivalDate("2026-08-14T15:44"); // Fri 14 Aug 2026, 15:44
125	
126	const state = {
127	  shows: [],
128	  venues: {},                  // venue code -> { name, address, postcode, lat, lng }
129	  markers: {},                 // id -> Leaflet marker
130	  clusterGroup: null,          // Leaflet.markercluster group for the non-focused pins
131	  map: null,
132	  selectedGenres: new Set(["Comedy"]),
133	  selectedSubgenres: new Set(), // finer descriptors; empty (or all) = every subgenre
134	  subgenreOptions: [],         // the subgenre values the panel currently offers
135	  priceFilter: "any",          // "any" | "free" | a cap in pounds, e.g. "15" ($ chip)
136	  travelMode: "Walking",
137	  maxTravelMinutes: DEFAULT_MAX_TRAVEL, // reach window from the travel card
138	  selectedTime: "",            // chosen exact start time, e.g. "16:30"
139	  selectedShowId: "",          // the pinned "next show" (destination)
140	  destLabel: "",               // editable destination text (defaults to the show's venue)
141	  destPlace: null,             // geocoded non-show destination { label, area, lat, lng, kind }
142	  destNote: "",                // label-only non-show destination (couldn't/didn't geocode)
143	  placeMarker: null,           // Leaflet marker for the geocoded place
144	  legShowId: "",               // a show clicked on the map (stop before the destination)
145	  editingCommitment: false,    // constraint panel opened from the plan to change it
146	  spareCtaDismissed: false,    // user hid the in-plan "time to spare" prompt
147	  bookCtaDismissed: false,     // user hid the "Need to book it?" question on a committed place
148	  viewMode: "closest",         // the one selector under the filters: "closest" | "soonest" | "map"
149	  view: "list",                // pane the mode implies: "map" | "list" (the list is default)
150	  sortBy: "distance",          // reachable-list order the mode implies: "time" | "distance"
151	  userLatLng: USER_DEFAULT,    // current "you are here" location
152	  userMarker: null,            // Leaflet marker for the user
153	  reachCircle: null,           // Leaflet circle for the travel radius
154	  routeLayers: [],             // Leaflet layers for the journey arrows/labels
155	  ready: false,                // booted + restored — only then do we write the cache
156	  savedPlan: null,             // cached plan awaiting judgement (see adoptRestoredPlan)
157	};
158	
159	/* ---------- Boot ---------- */
160	document.addEventListener("DOMContentLoaded", init);
161	
162	async function init() {
163	  renderDebugBanner();
164	  wireDebugControls();
165	  initMap();
166	  setUserLocation(USER_DEFAULT, { recenter: false }); // central-Edinburgh default
167	  requestUserLocation();                              // then ask for the real thing
168	  restoreNowState();      // last visit's filters (+ its plan, if still ahead of us)
169	  initIntro();            // the first-run explainer, unless it's been dismissed
170	  buildGenrePanel();
171	  buildPricePanel();
172	  buildTravelPanel();
173	  wirePanels();
174	  wireViewSwitch();
175	  // The header pin re-asks the browser for the user's location (same as the
176	  // map's ◎ control) and recentres on it.
177	  const locBtn = document.getElementById("locBtn");
178	  if (locBtn) locBtn.addEventListener("click", requestUserLocation);
179	  await loadShows();
180	  adoptRestoredPlan();    // the cached plan, now that we know today's shows
181	  buildSubgenrePanel();   // the option set comes from the loaded shows
182	  buildConstraintPanel();
183	  refreshMap();
184	  renderShowList();
185	  updateGenreValue();
186	  updateSubgenreValue();
187	  refreshFacetCounts();
188	  state.ready = true;     // from here on, every change is written to the cache
189	  saveNowState();
190	}
191	
192	/* ---------- Data loading ---------- */
193	/* How long a downloaded data file may be reused before we ask the network again
194	 * (shared/data-cache.js).
195	 *
196	 * The day file gets an HOUR, not a day, and the reason is this page's whole
197	 * premise: it answers "what can I get into right now", and the SOLD OUT stamps
198	 * it draws are refreshed hourly by the `refresh-tickets` task. A day-long reuse
199	 * would have been a cache that outlived its own data — a visitor returning after
200	 * lunch would see the morning's availability. An hour matches the refresh that
201	 * feeds it, so the page is never showing something staler than the pipeline can
202	 * make it.
203	 *
204	 * That still buys the reuse worth having. The url is keyed by date, so this only
205	 * ever concerns revisits within one day, and the common ones — a reload, a
206	 * reopened tab, a return an hour either side of a show — skip the download
207	 * entirely. The planner's catalogue is the file that earns a long TTL, and it
208	 * earns it by carrying no availability at all.
209	 *
210	 * venues.json holds for a day: it carries no ticket status, and its lookup lists
211	 * are append-only, so a copy fetched today decodes anything the day file can say.
212	 */
213	const DAY_TTL_MS = 60 * 60 * 1000;
214	const LOOKUPS_TTL_MS = DAY_MS;
215	
216	/* Load today's shows: the per-day file (only this fringe day's performances,
217	 * kept small) joined with the venue lookup (names + coordinates), reshaped for
218	 * the map and list. Only the current day is fetched, so the payload stays light.
219	 *
220	 * "Today" is the fringe day, 06:00 → 06:00 (shared/fringe-day.js), so the file
221	 * also carries tomorrow's small hours — the late shows someone at 23:50 is
222	 * actually looking for. Their `start` comes through extended ("24:30" for
223	 * 00:30), which is what keeps them sorting and comparing after 23:00 rather
224	 * than before 06:00. */
225	async function loadShows() {
226	  try {
227	    const [lookups, day] = await Promise.all([
228	      cachedFetchJson("data/venues.json", LOOKUPS_TTL_MS, noteCache),
229	      cachedFetchJson(`data/days/${NOW.fringeDate}.json`, DAY_TTL_MS, noteCache),
230	    ]);
231	    // The shared lookup file carries the venue map plus the global rooms/genres
232	    // lists that the day records index into. Fetched once.
233	    state.venues = lookups.venues;
234	    state.rooms = lookups.rooms || [];
235	    state.genres = lookups.genres || [];
236	    state.subgenres = lookups.subgenres || [];
237	    state.ticketStatuses = lookups.ticketStatuses || [];
238	    // Drop shows whose venue we couldn't geocode — they can't be placed on the map.
239	    state.shows = day
240	      .map((entry, i) => adaptShow(entry, state, i))
241	      .filter((s) => s.lat != null && s.lng != null);
242	  } catch (err) {
243	    console.error("Could not load show data:", err);
244	    state.shows = [];
245	  }
246	}
247	
248	/* Where the shared data cache (shared/data-cache.js) reports a cache write it
249	 * couldn't make or a stale copy it fell back on. Never surfaced in the UI: in
250	 * both cases the caller still got its data. */
251	function noteCache(err, url) {
252	  console.info("Data cache —", url, err);
253	}
254	
255	/* Join a minimal per-day record with its venue and expand to the model the map
256	 * and list expect ({ id, title, genre, venue, lat, lng, time, duration, price }).
257	 * The day record references genre, room, subgenres and ticket status by index
258	 * into the global `state.genres`/`state.rooms`/`state.subgenres`/
259	 * `state.ticketStatuses` lookup lists (room index -1, or an unknown room,
260	 * resolves to no room), and stores free/soldOut as 1/0. A show can perform more
261	 * than once a day, so the internal id is made unique per performance. */
262	function adaptShow(entry, { venues, rooms, genres, subgenres, ticketStatuses }, index) {
263	  const v = venues[entry.venue] || {};
264	  const venueName = v.name || (entry.venue ? `Venue ${entry.venue}` : "Venue TBC");
265	  const room = rooms[entry.room];
266	  const ticketStatus = (ticketStatuses || [])[entry.ts] || null;
267	  const price = typeof entry.pm === "number" ? entry.pm : entry.free ? 0 : null;
268	  return {
269	    id: `${entry.id}__${entry.start}__${index}`,
270	    showId: entry.id,
271	    slug: entry.slug,
272	    title: entry.title,
273	    genre: genres[entry.genre],
274	    subgenres: (entry.subs || []).map((i) => (subgenres || [])[i]).filter(Boolean),
275	    venue: room ? `${venueName} — ${room}` : venueName,
276	    lat: v.lat ?? null,
277	    lng: v.lng ?? null,
278	    time: entry.start,
279	    duration: entry.duration || 60,
280	    free: !!entry.free,
281	    // `pm` is THIS performance's cheapest band in pounds, absent when the price
282	    // cache doesn't know it — NOT the same as free (see shared/price.js).
283	    // priceMin is what the filter reads; `price` is the label a card renders.
284	    priceMin: price,
285	    price: priceLabel({ priceMin: price, free: !!entry.free }),
286	    soldOut: !!entry.soldOut,
287	    ticketStatus,
288	    // Can you actually get a ticket online? ticketStatus is the reliable signal
289	    // (the soldOut flag isn't — see scraper/SCRAPING.md). Unknown ⇒ assume yes.
290	    available: !NO_TICKETS_STATUSES.has(ticketStatus),
291	  };
292	}
293	
294	/* Ticket statuses that mean "no ticket available online" → SOLD OUT stamp.
295	 * Anything else (incl. unknown) is treated as available. */
296	const NO_TICKETS_STATUSES = new Set(["SOLD_OUT", "NO_ALLOCATION_CONTACT_VENUE"]);
297	
298	/* ---------- Map ---------- */
299	function initMap() {
300	  const map = L.map("leaflet-map", { scrollWheelZoom: false }).setView(EDINBURGH, 14);
301	  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
302	    maxZoom: 19,
303	    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
304	  }).addTo(map);
305	
306	
307	  state.map = map;
308	}
309	
310	/* ---------- User location ---------- */
311	function userIcon() {
312	  return L.divIcon({
313	    className: "user-marker",
314	    html: '<span class="user-dot"></span>',
315	    iconSize: [20, 20],
316	    iconAnchor: [10, 10],
317	  });
318	}
319	
320	/* Drop or move the "you are here" marker. opts.recenter pans the map to it. */
321	function setUserLocation(latlng, { recenter = true, real = false } = {}) {
322	  state.userLatLng = latlng;
323	  const label = real ? "You are here" : "You are here (approx. central Edinburgh)";
324	
325	  if (state.userMarker) {
326	    state.userMarker.setLatLng(latlng);
327	  } else {
328	    state.userMarker = L.marker(latlng, {
329	      icon: userIcon(),
330	      zIndexOffset: 1000,
331	      keyboard: false,
332	    }).addTo(state.map);
333	  }
334	  state.userMarker.bindPopup(`<p class="popup-title">${label}</p>`);
335	
336	  if (recenter && state.map) state.map.setView(latlng, 15, { animate: true });
337	  if (state.shows.length) refreshMap(); // reachable set depends on where we are
338	}
339	
340	/* Ask the browser for the user's real location and move the pin there. */
341	function requestUserLocation() {
342	  if (!("geolocation" in navigator)) {
343	    console.warn("Geolocation not supported; keeping default location.");
344	    return;
345	  }
346	  navigator.geolocation.getCurrentPosition(
347	    (pos) => {
348	      const here = [pos.coords.latitude, pos.coords.longitude];
349	      // Testing guard: outside the UK (e.g. an overseas tester) keep the
350	      // central-Edinburgh default and show the pre-set values instead.
351	      if (!isInUK(here)) {
352	        console.info(
353	          `Real location (${here[0].toFixed(3)}, ${here[1].toFixed(3)}) is outside the UK — ` +
354	            "keeping the central Edinburgh default for testing."
355	        );
356	        setDebugVisible(true);
357	        return;
358	      }
359	      // In the UK we trust the device, so every pre-set goes: the real location
360	      // replaces the default pin and the real clock replaces the simulated
361	      // "now". The debug tools that tweak them stay hidden.
362	      setUserLocation(here, { recenter: true, real: true });
363	      adoptRealClock();
364	    },
365	    (err) => {
366	      // Denied / unavailable / timed out — keep the central-Edinburgh default.
367	      // An unknown location is not a debug session, so the tools stay hidden.
368	      console.info("Using default location:", err && err.message);
369	    },
370	    { enableHighAccuracy: true, timeout: 8000, maximumAge: 60000 }
371	  );
372	}
373	
374	function genreColor(genre) {
375	  const map = {
376	    Comedy: "#c62024",
377	    Theatre: "#9c181b",
378	    "Dance, Physical Theatre & Circus": "#c79a36",
379	    Music: "#2f6bd6",
380	    "Cabaret and Variety": "#8e44ad",
381	    "Musicals and Opera": "#16a085",
382	    "Spoken Word": "#34495e",
383	    "Children's Shows": "#27ae60",
384	    Events: "#e67e22",
385	    Exhibitions: "#2c3e50",
386	  };
387	  return map[genre] || "#141414";
388	}
389	
390	
391	/* Does a show carry any of the selected subgenres? */
392	function matchesSubgenres(show) {
393	  return (show.subgenres || []).some((s) => state.selectedSubgenres.has(s));
394	}
395	
396	/* Both ends of a checkbox panel mean "don't narrow": none ticked is the obvious
397	 * one, and every box ticked is the same answer said the other way round. They
398	 * only look different — so a full panel filters nothing at all, which also
399	 * keeps the handful of shows carrying no subgenre (or a genre outside the ten
400	 * headline ones) in view instead of quietly dropping them. */
401	function genreFilterActive() {
402	  return state.selectedGenres.size > 0 && !allGenresSelected();
403	}
404	
405	function subgenreFilterActive() {
406	  return state.selectedSubgenres.size > 0 && !allSubgenresSelected();
407	}
408	
409	/* Shows passing the current taste filters (an empty *or* full genre/subgenre
410	 * set = all). `except` names one facet to leave unapplied — that's the pool a
411	 * facet's own per-option counts are measured against, so each count answers
412	 * "how many shows would ticking this give me", not "how many are already
413	 * showing". */
414	function filteredShows(except) {
415	  let list = state.shows;
416	  if (except !== "genre" && genreFilterActive()) {
417	    list = list.filter((s) => state.selectedGenres.has(s.genre));
418	  }
419	  if (except !== "subgenre" && subgenreFilterActive()) list = list.filter(matchesSubgenres);
420	  if (except !== "price") list = list.filter((s) => matchesPrice(s, state.priceFilter));
421	  return list;
422	}
423	
424	/* Shows passing every taste filter — what the map and list draw from. The
425	 * `except` argument is passed straight down from the count queries. */
426	function visibleShows(except) {
427	  return filteredShows(except);
428	}
429	
430	/* Candidate shows for the "next commitment" constraint. This is whatever the
431	 * user already has lined up, NOT part of the current genre/price search, so it
432	 * deliberately ignores the genre + price filter. Anything still ahead counts:
433	 * the time wheel offers every slot from now on, so the list under it has to
434	 * answer for those slots too — an hour the wheel offers but the list refuses to
435	 * populate reads as a bug. */
436	function constraintShows() {
437	  return state.shows.filter((s) => timeToMinutes(s.time) >= NOW.minutes);
438	}
439	
440	/* Minutes of travel, by the selected mode, from A to B ([lat,lng] each). */
441	function travelMinutes(a, b) {
442	  const speed = TRAVEL_SPEEDS_KMH[state.travelMode] || TRAVEL_SPEEDS_KMH.Walking;
443	  return (distanceKm(a, b) / speed) * 60;
444	}
445	
446	/* Metres covered in the chosen max-travel window at the selected travel speed. */
447	function reachRadiusMeters() {
448	  const speed = TRAVEL_SPEEDS_KMH[state.travelMode] || TRAVEL_SPEEDS_KMH.Walking;
449	  return speed * (state.maxTravelMinutes / 60) * 1000;
450	}
451	
452	/* The committed next commitment as a route/classification constraint: the
453	 * pinned show, or — when a typed place has been found on the map — a pseudo-show
454	 * carrying the place's coordinates and the picked time. Null while nothing with
455	 * coordinates is committed (a label-only place can't constrain anything
456	 * measurable). Everything downstream (classify, route, plan, Maps link) reads
457	 * the constraint through this, so shows and places behave identically. */
458	const PLACE_ID = "__place__"; // can't collide with show ids (`<id>__<start>__<index>`)
459	function commitmentConstraint() {
460	  const show = state.shows.find((s) => s.id === state.selectedShowId);
461	  if (show) return show;
462	  if (state.destPlace && state.selectedTime) {
463	    const p = state.destPlace;
464	    return { id: PLACE_ID, isPlace: true, time: state.selectedTime, lat: p.lat, lng: p.lng, duration: 0 };
465	  }
466	  return null;
467	}
468	
469	/* Classify a show for the map relative to the user and (optionally) the chosen
470	 * "next show" constraint. Returns "selected" | "ok" | "tight" | "hidden".
471	 *   - ok     : you can travel there and arrive before it starts
472	 *   - tight  : you'd arrive up to GRACE_MINUTES after it starts (faded)
473	 *   - hidden : out of reach, already missed, or won't leave time for your
474	 *              next show
475	 */
476	function classifyShow(show, constraint) {
477	  if (constraint && show.id === constraint.id) return "selected";
478	
479	  const here = state.userLatLng;
480	  const there = [show.lat, show.lng];
481	  const travel = travelMinutes(here, there);
482	  if (travel > state.maxTravelMinutes) return "hidden"; // beyond chosen travel window
483	
484	  const arrival = NOW.minutes + travel;
485	  const start = timeToMinutes(show.time);
486	  const reachInTime = arrival <= start;
487	  const tight = !reachInTime && arrival - start <= GRACE_MINUTES;
488	
489	  // With a next show chosen, also require leaving in time to make it.
490	  if (constraint) {
491	    const end = start + show.duration;
492	    const onward = travelMinutes(there, [constraint.lat, constraint.lng]);
493	    const makesConstraint = end + onward <= timeToMinutes(constraint.time);
494	    if (!makesConstraint) return "hidden";
495	    // Once committed to a plan, only keep shows you can comfortably reach.
496	    return reachInTime ? "ok" : "hidden";
497	  }
498	
499	  if (reachInTime) return "ok";
500	  if (tight) return "tight";
501	  return "hidden";
502	}
503	
504	/* The shows to draw on the map, each with its status. */
505	function displayedShows(except) {
506	  const constraint = commitmentConstraint();
507	
508	  const out = [];
509	  visibleShows(except).forEach((show) => {
510	    const status = classifyShow(show, constraint);
511	    if (status !== "hidden") out.push({ show, status });
512	  });
513	  // Always keep the chosen next show pinned, even if it's beyond the circle.
514	  // (A committed place isn't a show — it gets its own pin in renderPlaceMarker.)
515	  if (constraint && !constraint.isPlace && !out.some((o) => o.show.id === constraint.id)) {
516	    out.push({ show: constraint, status: "selected" });
517	  }
518	  // Keep the user's selected show pinned too — it stays selected until they
519	  // change it, even if the current commitment/window would otherwise hide it.
520	  if (
521	    state.legShowId &&
522	    state.legShowId !== state.selectedShowId &&
523	    !out.some((o) => o.show.id === state.legShowId)
524	  ) {
525	    const sel = state.shows.find((s) => s.id === state.legShowId);
526	    if (sel) out.push({ show: sel, status: "leg" });
527	  }
528	  // Highlight the show the user selected — a stop before the destination when a
529	  // plan exists, or just the highlighted pin otherwise.
530	  if (state.legShowId) {
531	    const focus = out.find((o) => o.show.id === state.legShowId && o.status !== "selected");
532	    if (focus) focus.status = "leg";
533	  }
534	  // Draw highlighted pins last so they sit on top.
535	  const z = { ok: 0, tight: 0, leg: 1, selected: 2 };
536	  out.sort((a, b) => (z[a.status] || 0) - (z[b.status] || 0));
537	  return out;
538	}
