669	function renderReachCircle() {
670	  if (!state.map) return;
671	  const opts = {
672	    radius: reachRadiusMeters(),
673	    color: "#6c4cf1",
674	    weight: 1.5,
675	    fillColor: "#6c4cf1",
676	    fillOpacity: 0.08,
677	    interactive: false,
678	  };
679	  if (state.reachCircle) {
680	    state.reachCircle.setLatLng(state.userLatLng).setRadius(opts.radius);
681	  } else {
682	    state.reachCircle = L.circle(state.userLatLng, opts).addTo(state.map);
683	  }
684	  state.reachCircle.bindTooltip(
