689	
690	function renderMarkers() {
691	  if (!state.map) return;
692	
693	  // Cluster group for the ordinary pins — collapses dense / overlapping shows
694	  // into a count bubble that splits (and spiderfies coincident pins) on zoom.
695	  // Guarded: if the plugin CDN failed to load, we degrade to plain markers so
696	  // the map still works rather than throwing.
697	  if (!state.clusterGroup && typeof L.markerClusterGroup === "function") {
698	    state.clusterGroup = L.markerClusterGroup({
699	      maxClusterRadius: 26,      // px; smaller = only genuinely close pins merge
700	      spiderfyOnMaxZoom: true,   // fan out pins sharing a spot when fully zoomed
701	      showCoverageOnHover: false,
702	      iconCreateFunction: clusterIcon,
703	    });
704	    state.map.addLayer(state.clusterGroup);
705	  }
706	
707	  // Clear the previous render: clustered pins live in the group, the focused /
708	  // destination pins are added straight to the map, so clear both.
709	  if (state.clusterGroup) state.clusterGroup.clearLayers();
710	  Object.values(state.markers).forEach((m) => {
711	    if (state.map.hasLayer(m)) state.map.removeLayer(m);
712	  });
713	  state.markers = {};
714	
715	  // Only when the user has actually tapped a show to focus it do the other pins
716	  // step back — a committed next commitment on its own shouldn't grey out the
717	  // options you're browsing to fill the gap.
718	  const anyFocus = Boolean(state.legShowId);
719	  displayedShows().forEach(({ show, status }) => {
720	    const prominent = status === "selected" || status === "leg";
721	    const dim = anyFocus && !prominent;
722	    const marker = L.marker([show.lat, show.lng], {
723	      icon: genrePin(show, status),
724	      zIndexOffset: status === "selected" ? 1000 : status === "leg" ? 600 : 0,
725	      keyboard: false,
726	    });
727	    marker.setOpacity(dim ? 0.25 : status === "tight" ? 0.55 : 1);
728	
729	    if (prominent) {
730	      // Keep the highlighted pins out of clusters so they're always visible.
731	      // (No name tooltip — the focus card / plan carries the title; a permanent
732	      // label here just added noise. The ✓-arrival time sits above instead.)
733	      marker.addTo(state.map);
734	    } else if (state.clusterGroup) {
735	      state.clusterGroup.addLayer(marker);
736	    } else {
737	      marker.addTo(state.map); // plugin unavailable — plain marker fallback
738	    }
739	
740	    // Tapping a pin selects the show (updates the map + draws its path) but,
741	    // unlike the list, does NOT scroll the page — map browsing stays put.
742	    marker.on("click", () => onShowClick(show));
743	    state.markers[show.id] = marker;
744	  });
745	}
