747	/* Select a show (from the list or a map pin): it becomes the stop on the way to
748	 * any commitment, draws its path, and the other pins dim. Selecting it again
749	 * clears it. The list additionally scrolls up to the plan; the map does not. The
750	 * committed destination itself isn't a re-selectable focus. */
751	function onShowClick(show) {
752	  if (show.id === state.selectedShowId) return; // already the committed destination
753	  state.legShowId = state.legShowId === show.id ? "" : show.id; // toggle selection
754	  refreshMap();
755	}
