757	/* ---------- Journey arrows ---------- */
758	function renderRoute() {
759	  if (!state.map) return;
760	  // Clear previous arrows/labels.
761	  state.routeLayers.forEach((l) => state.map.removeLayer(l));
762	  state.routeLayers = [];
763	
764	  const dest = commitmentConstraint();
765	
766	  // No commitment yet, but a show is selected: still draw the walk to it, with
767	  // the same travel pill and the ✓ "you make its start" check.
768	  if (!dest) {
769	    const sel = state.legShowId ? state.shows.find((s) => s.id === state.legShowId) : null;
770	    if (sel) {
771	      drawLeg(state.userLatLng, [sel.lat, sel.lng], { checkMin: timeToMinutes(sel.time) });
772	    }
773	    return;
774	  }
775	  const destPt = [dest.lat, dest.lng];
776	
777	  // Is there a valid intermediate stop the user clicked?
778	  let leg = null;
779	  if (state.legShowId && state.legShowId !== dest.id) {
780	    const cand = state.shows.find((s) => s.id === state.legShowId);
781	    if (cand && classifyShow(cand, dest) === "ok") leg = cand;
782	  }
783	
784	  if (leg) {
785	    const legPt = [leg.lat, leg.lng];
786	    // Leg 1: leave now, arrive before this show starts.
787	    drawLeg(state.userLatLng, legPt, {
788	      checkMin: timeToMinutes(leg.time), // show start (your arrival is before this)
789	    });
790	    // Leg 2: leave when this show ends, arrive before your next commitment.
791	    drawLeg(legPt, destPt, {
792	      checkMin: timeToMinutes(dest.time), // constraint start
793	    });
794	  } else {
795	    // Single leg: leave now, arrive before your next commitment.
796	    drawLeg(state.userLatLng, destPt, { checkMin: timeToMinutes(dest.time) });
797	  }
798	}
