800	/* Draw one animated arrow leg. The green check above the destination pin shows
801	 * the deadline that arrival comfortably beats (a show start, or your next
802	 * commitment). The leg's clock window lives in the itinerary, not on the map. */
803	function drawLeg(from, to, { checkMin } = {}) {
804	  const line = L.polyline([from, to], {
805	    className: "route-line",
806	    color: "#141414",
807	    weight: 3,
808	    opacity: 0.9,
809	    interactive: false,
810	  }).addTo(state.map);
811	  state.routeLayers.push(line);
812	
813	  // Arrowhead near the destination end, rotated to the bearing.
814	  const head = L.marker(lerp(from, to, 0.82), {
815	    icon: L.divIcon({
816	      className: "route-arrow-wrap",
817	      html: `<span class="route-arrow" style="transform:rotate(${bearing(from, to)}deg)"></span>`,
818	      iconSize: [16, 16],
819	      iconAnchor: [8, 8],
820	    }),
821	    interactive: false,
822	    keyboard: false,
823	  }).addTo(state.map);
824	  state.routeLayers.push(head);
825	
826	  // Green check with the deadline you're beating, sitting directly above the
827	  // destination pin. The marker root is a zero-size anchor pinned exactly on the
828	  // point; the visible pill is an inner span, so its centring transform survives
829	  // (Leaflet writes its own inline transform on the root to place it, which would
830	  // otherwise clobber a transform set on the root itself).
831	  if (checkMin != null) {
832	    const chk = L.marker(to, {
833	      icon: L.divIcon({
834	        className: "route-check-marker",
835	        html: `<span class="route-label route-check"><span class="tick">✓</span> ${minutesToTime(checkMin)}</span>`,
836	        iconSize: [0, 0],
837	        iconAnchor: [0, 0],
838	      }),
839	      interactive: false,
840	      keyboard: false,
841	      zIndexOffset: 1100,
842	    }).addTo(state.map);
843	    state.routeLayers.push(chk);
844	  }
845	}
