851	/* The verb for a leg, matching the selected travel mode: "5 min walk" /
852	 * "5 min by taxi" / "5 min by bike". Keeps the itinerary honest when the mode
853	 * switches away from walking. */
854	function travelVerb() {
855	  return { Walking: "walk", "Taxi/Car": "by taxi", Bicycle: "by bike" }[state.travelMode] || "walk";
