858	/* ---------- Show list ---------- */
859	/* The list mirrors what's on the map, minus the chosen next commitment: that
860	 * show is a future destination the user has already locked in, not something
861	 * "Happening Now", so we pin it on the map but keep it out of this list. */
862	/* How many list rows to show before the "Show more" button; grows on demand. */
863	const SHOW_PAGE = 12;
864	
865	/* The reachable shows to list (excluding the chosen next show). Without a
866	 * commitment, "on now" means the next couple of hours — not the whole day — so
867	 * the list stays about spontaneity, not a full catalogue. Order-independent:
868	 * the caller sorts by time or distance. */
869	function fittingShows(except) {
870	  const constraint = commitmentConstraint();
871	  const constrained = Boolean(constraint);
872	  let all = displayedShows(except).filter(({ show }) => show.id !== state.selectedShowId);
873	  // A selected show that can't actually be slipped in before the commitment isn't
874	  // a real option — keep it on the map and the itinerary, but out of this list
875	  // and its count (so "N shows you can slip in" stays honest).
876	  if (constraint && state.legShowId) {
877	    const leg = state.shows.find((s) => s.id === state.legShowId);
878	    if (leg && classifyShow(leg, constraint) !== "ok") {
879	      all = all.filter(({ show }) => show.id !== state.legShowId);
880	    }
881	  }
882	  if (!constrained) {
883	    all = all.filter(({ show }) => timeToMinutes(show.time) <= NOW.minutes + 120);
884	  }
885	  return all;
886	}
