888	function renderShowList() {
889	  const grid = document.getElementById("showsGrid");
890	  const title = document.querySelector(".shows-title");
891	  const moreBtn = document.getElementById("showMore");
892	  if (!grid) return;
893	  grid.innerHTML = "";
894	
895	  const constraint = commitmentConstraint();
896	
897	  const all = fittingShows();
898	  // Walk minutes: computed once, reused for the row label and distance sort.
899	  all.forEach((o) => {
900	    o.walk = Math.max(1, Math.round(travelMinutes(state.userLatLng, [o.show.lat, o.show.lng])));
901	  });
902	  const byDistance = state.sortBy === "distance";
903	  if (byDistance) all.sort((a, b) => a.walk - b.walk || a.show.time.localeCompare(b.show.time));
904	  else all.sort((a, b) => a.show.time.localeCompare(b.show.time));
905	
906	  if (title) {
907	    const n = all.length;
908	    const shows = n === 1 ? "show" : "shows";
909	    title.textContent = constraint
910	      ? `${n} ${shows} you can slip in before ${clockLabel(constraint.time)}`
911	      : `${n} ${shows} you could wander into right now`;
912	  }
913	
914	  if (!all.length) {
915	    grid.innerHTML =
916	      '<p class="show-meta">' +
917	      (constraint
918	        ? "Nothing fits before your next commitment — try a later time or a wider travel window."
919	        : "Nothing reachable in the next couple of hours — widen your travel window or taste.") +
920	      "</p>";
921	    if (moreBtn) moreBtn.hidden = true;
922	    return;
923	  }
924	
925	  const cap = state.showCap || SHOW_PAGE;
926	  const shown = all.slice(0, cap);
927	
928	  // Compact rows. Sorting by time groups under start-time headings; sorting by
929	  // distance is a flat nearest-first list (each row still shows its time).
930	  let group = null;
931	  shown.forEach(({ show, status, walk }) => {
932	    if (!byDistance && show.time !== group) {
933	      group = show.time;
934	      const head = document.createElement("h3");
935	      head.className = "shows-group-head";
936	      head.textContent = clockLabel(show.time);
937	      grid.appendChild(head);
938	    }
939	    const item = document.createElement("article");
940	    item.className = `show-item show-item--${status}${show.available ? "" : " show-item--soldout"}`;
941	    item.tabIndex = 0;
942	    item.setAttribute("role", "button");
943	    item.innerHTML = `
944	      ${showStamp(show, status)}
945	      <span class="si-main">
946	        <span class="show-genre">${escapeHtml(show.genre)}</span>
947	        <span class="show-name">${escapeHtml(show.title)}</span>
948	        <span class="show-meta">${escapeHtml(show.venue)}</span>
949	        ${subgenreTags(show)}
950	      </span>
951	      <span class="si-side">
952	        <span class="si-time">${escapeHtml(clockLabel(show.time))}</span><br />
953	        <span class="si-walk">🚶 ${walk} min · ${escapeHtml(show.price)}</span>
954	        ${constraint ? '<br /><span class="si-fits">fits</span>' : ""}
955	      </span>`;
956	    const activate = () => {
957	      onShowClick(show);
958	      // Selecting from the list promotes the show into the plan at the top of the
959	      // page — scroll all the way up so the whole itinerary reads top-to-bottom
960	      // (scrolling only to the plan tucked its header under the sticky nav).
961	      if (state.legShowId === show.id) {
962	        window.scrollTo({ top: 0, behavior: "smooth" });
963	      }
964	    };
965	    item.addEventListener("click", activate);
966	    item.addEventListener("keydown", (e) => {
967	      if (e.key === "Enter" || e.key === " ") {
968	        e.preventDefault();
969	        activate();
970	      }
971	    });
972	    grid.appendChild(item);
973	  });
974	
975	  if (moreBtn) {
976	    const remaining = all.length - shown.length;
977	    moreBtn.hidden = remaining <= 0;
978	    moreBtn.textContent = `Show ${Math.min(SHOW_PAGE, remaining)} more · ${remaining} left`;
979	  }
980	}
