982	/* ---------- View selector: Closest | Soonest | Map ---------- */
983	/* One control carries both decisions. The map and the reachable list are two
984	 * views of the same shows, and the list only ever has two useful orders — so
985	 * rather than a view toggle plus a sort toggle, the three positions here are
986	 * the three things you can actually be looking at. The filters above act on all
987	 * three, so nothing here touches them.
988	 *
989	 * "Closest" leads and is the default: a ranked list answers "what can I make?"
990	 * directly, where the map asks the user to do the ranking themselves by eye.
991	 * The map sits third as the orientation view you reach for once you know what
992	 * the options are. */
993	const VIEW_MODES = {
994	  closest: { view: "list", sortBy: "distance" },
