1072	/* ---------- Journey strip ---------- */
1073	/* A narrow, always-visible timeline between the filters and the map. It mirrors
1074	 * the journey the map is drawing, left → right:
1075	 *   • origin  — "You are here", now (always shown, styled dull)
1076	 *   • middle  — nothing chosen yet: an animated walker idling in place;
1077	 *               a destination chosen: the leg(s) to it with travel time + slack
1078	 *   • right   — your next commitment, once chosen
1079	 * The slack chip notes how long you'd have before each show starts. */
1080	function renderJourneyStrip() {
1081	  const strip = document.getElementById("journeyStrip");
1082	  if (!strip) return;
1083	
1084	  const origin = state.userLatLng;
1085	  const constraint = commitmentConstraint();
1086	  // The selected show to slip in — kept independent of the commitment. It shows
1087	  // in the plan whenever one is selected (and it isn't the commitment itself),
1088	  // even if it no longer neatly fits: the slack chip tells that story.
1089	  const leg =
1090	    state.legShowId && (!constraint || state.legShowId !== constraint.id)
1091	      ? state.shows.find((s) => s.id === state.legShowId)
1092	      : null;
1093	
1094	  // Nothing chosen at all — no plan to show; the list heading carries the state.
1095	  if (!constraint && !leg && !state.destNote) {
1096	    strip.innerHTML = "";
1097	    return;
1098	  }
1099	
1100	  // The plan header carries a mild "open in Maps" link on its right (only useful
1101	  // once there's a commitment to route toward) — a quiet offer, not a big button.
1102	  const parts = [
1103	    '<div class="plan-head-row">' +
1104	      '<p class="plan-head">Your plan</p>' +
1105	      (constraint
1106	        ? '<a id="mapsRouteLink" class="plan-maps-mild" href="#" target="_blank" rel="noopener" ' +
1107	          'title="Open this route in Google Maps">' + GMAPS_LOGO + " Open in Maps</a>"
1108	        : "") +
1109	    "</div>",
1110	  ];
1111	  parts.push(planNode("📍", "you", `${NOW.time} · now`, "You are here", state.travelMode.toLowerCase(), "", ""));
1112	
1113	  if (leg) {
1114	    const legPt = [leg.lat, leg.lng];
1115	    const arriveLeg = NOW.minutes + travelMinutes(origin, legPt);
1116	    // Can you slip this show in and still make the commitment? If not, the show —
1117	    // not the commitment — is where the problem belongs.
1118	    const legFits = !constraint || classifyShow(leg, constraint) === "ok";
1119	
1120	    parts.push(planLeg(travelMinutes(origin, legPt)));
1121	    parts.push(
1122	      planNode(
1123	        genreIcon(leg.genre),
1124	        "stop",
1125	        `${clockLabel(leg.time)}–${minutesToTime(timeToMinutes(leg.time) + leg.duration)}`,
1126	        leg.title,
1127	        `${leg.venue} · ${leg.genre}`,
1128	        legFits
1129	          ? planSlack(timeToMinutes(leg.time) - arriveLeg)
1130	          : '<span class="plan-slack wontfit">You\'ll be late</span>',
1131	        `${subgenreTags(leg)}${planBuy(leg)}`
1132	      )
1133	    );
1134	    if (constraint) {
1135	      const destPt = [constraint.lat, constraint.lng];
1136	      if (legFits) {
1137	        // Sequential detour: leave when the show ends, then on to the commitment.
1138	        const departFromLeg = timeToMinutes(leg.time) + leg.duration;
1139	        const arriveDest = departFromLeg + travelMinutes(legPt, destPt);
1140	        parts.push(planLeg(travelMinutes(legPt, destPt)));
1141	        parts.push(destNode(constraint, planSlack(timeToMinutes(constraint.time) - arriveDest)));
1142	      } else {
1143	        // The show breaks this plan — present the commitment as reachable directly
1144	        // (skip the show), with no alarming pill of its own: it isn't the problem.
1145	        const arriveDest = NOW.minutes + travelMinutes(origin, destPt);
1146	        parts.push(planLeg(travelMinutes(origin, destPt)));
1147	        parts.push(destNode(constraint, planSlack(timeToMinutes(constraint.time) - arriveDest)));
1148	      }
1149	    } else if (state.destNote) {
1150	      parts.push(noteLeg(), noteDestNode());
1151	    }
1152	  } else if (!constraint) {
1153	    // A note commitment only: no coordinates, so no travel time or slack — the
1154	    // node keeps the commitment visible and editable, nothing more.
1155	    parts.push(noteLeg(), noteDestNode());
1156	  } else {
1157	    const destPt = [constraint.lat, constraint.lng];
1158	    const arriveDest = NOW.minutes + travelMinutes(origin, destPt);
1159	    // Middle slot: until a show is slipped in, offer the plan's spare time as a
1160	    // prompt where the chosen show will go. It's dismissable, and gets replaced
