1172	  wireNodeControls(strip.querySelector(".plan-node.stop"), {
1173	    change: () =>
1174	      document.getElementById("shows")?.scrollIntoView({ behavior: "smooth", block: "start" }),
1175	    remove: () => { state.legShowId = ""; refreshMap(); },
1176	    changeLabel: "Pick a different show",
1177	    removeLabel: "Remove selected show",
1178	  });
