1221	/* Build the Google Maps URL for the current plan. The journey always starts at
1222	 * "you are here"; the shape depends on how many stops are chosen on top of it:
1223	 *   • none           → just open the map centred on the user.
1224	 *   • one (chosen OR
1225	 *     destination)   → directions from here to that single show.
1226	 *   • two (chosen +
1227	 *     destination)   → directions here → chosen show → destination, with the
1228	 *                      chosen show passed as a waypoint.
1229	 * Travel mode follows the user's selection. */
1230	function googleMapsUrl() {
1231	  const origin = state.userLatLng; // [lat, lng] — "you are here"
1232	  const fmt = ([lat, lng]) => `${lat},${lng}`;
1233	
1234	  const destShow = commitmentConstraint(); // a committed place routes the same way
1235	  let legShow = null;
1236	  if (state.legShowId && (!destShow || state.legShowId !== destShow.id)) {
1237	    legShow = state.shows.find((s) => s.id === state.legShowId) || null;
1238	  }
1239	
1240	  // Ordered geographic stops after the origin: chosen show first, then the
1241	  // destination. The final one is the route's destination; any before it are
1242	  // waypoints.
1243	  const stops = [];
1244	  if (legShow) stops.push([legShow.lat, legShow.lng]);
1245	  if (destShow) stops.push([destShow.lat, destShow.lng]);
1246	
1247	  // Nothing chosen — just open the map centred on the user.
1248	  if (stops.length === 0) {
1249	    return `https://www.google.com/maps/@${fmt(origin)},15z`;
1250	  }
1251	
1252	  const destination = stops[stops.length - 1];
1253	  const waypoints = stops.slice(0, -1);
1254	  let url =
1255	    "https://www.google.com/maps/dir/?api=1" +
1256	    `&origin=${encodeURIComponent(fmt(origin))}` +
1257	    `&destination=${encodeURIComponent(fmt(destination))}` +
1258	    `&travelmode=${googleMapsTravelMode()}`;
1259	  if (waypoints.length) {
1260	    url += `&waypoints=${encodeURIComponent(waypoints.map(fmt).join("|"))}`;
1261	  }
1262	  return url;
1263	}
