1274	/* Minutes of slack before the next commitment on the current plan — i.e. the
1275	 * free time you could still fill with a show. Accounts for a chosen leg. Returns
1276	 * null when no commitment is set. */

1277	function planSpareMinutes() {
1278	  const constraint = commitmentConstraint();
1279	  if (!constraint) return null;
1280	
1281	  const origin = state.userLatLng;
1282	  const destPt = [constraint.lat, constraint.lng];
1283	
1284	  let leg = null;
1285	  if (state.legShowId && state.legShowId !== constraint.id) {
1286	    const cand = state.shows.find((s) => s.id === state.legShowId);
1287	    if (cand && classifyShow(cand, constraint) === "ok") leg = cand;
