1	// Travel-time estimation between Fringe venues.
2	//
3	// Pure — no DOM, no fetch. Ported from the home site's js/app.js (the haversine
4	// `distanceKm` and the `TRAVEL_SPEEDS_KMH` table) so the planner estimates
5	// travel between two shows the same way the "Now" map does. The scheduling
6	// engine uses this to size the gap it requires between back-to-back shows at
7	// different venues, and the schedule graphic uses it to label the travel leg
8	// drawn between two shows less than an hour apart.
9	
10	// The three ways the planner lets you get between venues. Short, stable keys —
11	// the UI maps them to labels/emoji (🚶 🚲 🚗). Matches the home site's three
12	// modes (there is no bus mode: we can't give honest headway-aware bus times).
13	export const TRAVEL_MODES = ["walk", "bike", "car"];
14	
15	// Rough door-to-door speeds (km/h) used to turn crow-flies distance into a
16	// travel estimate.
17	export const TRAVEL_SPEED_KMH = {
18	  // Walking is dialled down to ~2/3 of a brisk 5 km/h — Edinburgh's closes,
19	  // hills, stairs and festival crowds make real walking slower than the map
20	  // distance suggests. (Same figure as js/app.js.)
21	  walk: (5 * 2) / 3, // ≈ 3.33 km/h
22	  bike: 15,
23	  // A car in the congested August city centre is only a little quicker than a
24	  // bike once you count one-way systems, closures and parking.
25	  car: 22,
26	};
27	
28	export const DEFAULT_TRAVEL_MODE = "walk";
29	
30	/** Normalize a coordinate given as {lat,lng} or [lat,lng] to [lat,lng], or
31	 *  null when either component is missing (unknown / online venue). */
32	function coordPair(c) {
33	  if (!c) return null;
34	  let lat, lng;
35	  if (Array.isArray(c)) {
36	    [lat, lng] = c;
37	  } else {
38	    lat = c.lat;
39	    lng = c.lng;
40	  }
41	  if (lat == null || lng == null || Number.isNaN(lat) || Number.isNaN(lng)) return null;
42	  return [Number(lat), Number(lng)];
43	}
44	
45	/**
46	 * Great-circle distance in kilometres between two points (haversine). Accepts
47	 * either {lat,lng} objects or [lat,lng] pairs. Returns null if either point has
48	 * no usable coordinates.
49	 * @param {{lat:number,lng:number}|[number,number]} a
50	 * @param {{lat:number,lng:number}|[number,number]} b
51	 * @returns {number|null}
52	 */
53	export function distanceKm(a, b) {
54	  const pa = coordPair(a);
55	  const pb = coordPair(b);
56	  if (!pa || !pb) return null;
57	  const [lat1, lng1] = pa;
58	  const [lat2, lng2] = pb;
59	  const R = 6371;
60	  const toRad = (d) => (d * Math.PI) / 180;
61	  const dLat = toRad(lat2 - lat1);
62	  const dLng = toRad(lng2 - lng1);
63	  const h =
64	    Math.sin(dLat / 2) ** 2 +
65	    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
66	  return 2 * R * Math.asin(Math.sqrt(h));
67	}
68	
69	/**
70	 * Estimated travel time in minutes between two venues by the given mode.
71	 * Returns null when the distance can't be computed (an online venue or a venue
72	 * we have no coordinates for) so the caller can fall back to a flat buffer.
73	 * @param {{lat:number,lng:number}|[number,number]} a
74	 * @param {{lat:number,lng:number}|[number,number]} b
75	 * @param {"walk"|"bike"|"car"} [mode]
76	 * @returns {number|null}
77	 */
78	export function travelMinutes(a, b, mode = DEFAULT_TRAVEL_MODE) {
79	  const km = distanceKm(a, b);
80	  if (km == null) return null;
81	  const speed = TRAVEL_SPEED_KMH[mode] ?? TRAVEL_SPEED_KMH[DEFAULT_TRAVEL_MODE];
82	  return (km / speed) * 60;
83	}
