1	// Port of edfringe/favorites.py — parse a favourites export into a de-duplicated
2	// list of show slugs. Pure, no I/O: the caller reads the file text and passes it
3	// in (browser FileReader or Node fs), this module never touches the filesystem.
4	
5	// Matches https://www.edfringe.com/tickets/whats-on/<slug> (with or without
6	// "www.", case-insensitive scheme/host), capturing the slug.
7	const URL_RE = /https?:\/\/(?:www\.)?edfringe\.com\/tickets\/whats-on\/([a-z0-9-]+)/i;
8	const SLUG_RE = /^[a-z0-9-]+$/i;
9	
10	/**
11	 * Extract the show slug from a full edfringe show URL, or fall back to the
12	 * last non-empty path segment if the URL doesn't match the expected host/path.
13	 * @param {string} url
14	 * @returns {string}
15	 */
16	export function slugFromUrl(url) {
17	  const m = URL_RE.exec(url);
18	  if (m) return m[1];
19	  return url.replace(/\/+$/, "").split("/").pop();
20	}
21	
22	/**
23	 * Build the canonical edfringe show URL from a slug.
24	 * @param {string} slug
25	 * @returns {string}
26	 */
27	export function urlFromSlug(slug) {
28	  return `https://www.edfringe.com/tickets/whats-on/${slug}`;
29	}
30	
31	// --- CSV parsing (RFC 4180-ish: quoted fields, "" escaped quote, CRLF/LF) ---
32	
33	/**
34	 * Parse CSV text into rows of cells. Handles quoted fields (with embedded
35	 * commas/newlines/escaped "" quotes) and both CRLF and LF line endings.
36	 * @param {string} text
37	 * @returns {string[][]}
38	 */
39	function parseCsv(text) {
40	  const rows = [];
41	  let row = [];
42	  let cell = "";
43	  let inQuotes = false;
44	  let i = 0;
45	  const n = text.length;
46	
47	  const endCell = () => {
48	    row.push(cell);
49	    cell = "";
50	  };
51	  const endRow = () => {
52	    endCell();
53	    rows.push(row);
54	    row = [];
55	  };
56	
57	  while (i < n) {
58	    const ch = text[i];
59	    if (inQuotes) {
60	      if (ch === '"') {
61	        if (text[i + 1] === '"') {
62	          cell += '"';
63	          i += 2;
64	          continue;
65	        }
66	        inQuotes = false;
67	        i += 1;
68	        continue;
69	      }
70	      cell += ch;
71	      i += 1;
72	      continue;
73	    }
74	    if (ch === '"') {
75	      inQuotes = true;
76	      i += 1;
77	      continue;
78	    }
79	    if (ch === ",") {
80	      endCell();
81	      i += 1;
82	      continue;
83	    }
84	    if (ch === "\r") {
85	      // Treat \r\n and lone \r as a single row terminator.
86	      if (text[i + 1] === "\n") i += 1;
87	      endRow();
88	      i += 1;
89	      continue;
90	    }
91	    if (ch === "\n") {
92	      endRow();
93	      i += 1;
94	      continue;
95	    }
96	    cell += ch;
97	    i += 1;
98	  }
99	  // Flush trailing cell/row (file may or may not end with a newline).
100	  if (cell !== "" || row.length > 0) {
101	    endRow();
102	  }
103	  return rows;
104	}
105	
106	/** Strip a leading UTF-8 BOM (U+FEFF) if present. */
107	function stripBom(text) {
108	  return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
109	}
110	
111	/**
112	 * Scan every cell of CSV text for edfringe show URLs, collecting de-duplicated
113	 * slugs in first-seen order. Mirrors favorites.py's `_from_csv`.
114	 * @param {string} text
115	 * @returns {string[]}
116	 */
117	function slugsFromCsvText(text) {
118	  const slugs = [];
119	  const seen = new Set();
120	  const rows = parseCsv(stripBom(text));
121	  for (const row of rows) {
122	    for (const cell of row) {
123	      const m = URL_RE.exec(cell || "");
124	      if (m && !seen.has(m[1])) {
125	        seen.add(m[1]);
126	        slugs.push(m[1]);
127	      }
128	    }
129	  }
130	  return slugs;
131	}
132	
133	/**
134	 * Fallback parser for a plain newline-delimited list of slugs/URLs (one per
135	 * line, "#" comments and blank lines ignored). Mirrors favorites.py's `_from_txt`.
136	 * @param {string} text
137	 * @returns {string[]}
138	 */
139	function slugsFromTxtText(text) {
140	  const slugs = [];
141	  const seen = new Set();
142	  for (let line of stripBom(text).split(/\r\n|\r|\n/)) {
143	    line = line.trim();
144	    if (!line || line.startsWith("#")) continue;
145	    const m = URL_RE.exec(line);
146	    const slug = m ? m[1] : (SLUG_RE.test(line) ? line : null);
147	    if (slug && !seen.has(slug)) {
148	      seen.add(slug);
149	      slugs.push(slug);
150	    }
151	  }
152	  return slugs;
153	}
154	
155	/**
156	 * Parse a favourites export (CSV text, or a plain newline list of URLs/slugs
157	 * as a fallback) into a de-duplicated list of show slugs, first-seen order.
158	 *
159	 * Detection: if any edfringe show URL is found via the CSV scan, use that
160	 * result. Otherwise fall back to line-based parsing (handles a plain .txt
161	 * paste, or a CSV with no URL-bearing cells but slug-like lines).
162	 * @param {string} text raw file contents (CSV or newline list)
163	 * @returns {string[]} de-duplicated slugs, in first-seen order
164	 */
165	export function parseFavourites(text) {
166	  if (text == null) return [];
167	  const csvSlugs = slugsFromCsvText(text);
168	  if (csvSlugs.length > 0) return csvSlugs;
169	  return slugsFromTxtText(text);
170	}
