2213	/* Animate a counter from its current value to `to`. */
2214	function tweenCount(el, to) {
2215	  const reduce = window.matchMedia && matchMedia("(prefers-reduced-motion:reduce)").matches;
2216	  el.classList.remove("bump");
2217	  void el.offsetWidth;
2218	  el.classList.add("bump");
2219	  const from = parseInt(el.textContent, 10);
2220	  if (reduce || isNaN(from) || from === to) {
2221	    el.textContent = String(to);
2222	    return;
2223	  }
2224	  let t0 = null;
2225	  const dur = 380;
2226	  function step(ts) {
2227	    if (t0 === null) t0 = ts;
2228	    const p = Math.min(1, (ts - t0) / dur);
2229	    el.textContent = String(Math.round(from + (to - from) * (1 - Math.pow(1 - p, 3))));
2230	    if (p < 1) requestAnimationFrame(step);
2231	  }
2232	  requestAnimationFrame(step);
2233	}
