2263	/* ---------- Remembering the page between visits ----------
2264	 * Everything the user set on this page — the taste filters, how they're
2265	 * travelling, which view they're in, and the plan itself — is cached in
2266	 * localStorage and restored on the next visit, so coming back doesn't mean
2267	 * setting it all up again.
2268	 *
2269	 * The filters are timeless and always come back. The plan isn't: a commitment
2270	 * at 18:00 or a show you'd picked that has already started is no longer a plan,
2271	 * it's history. Those are simply dropped — a plan whose time has gone is not
2272	 * worth handing back, so there's nothing to offer and nothing to dismiss. */
2273	const STORE_KEY = "edfringenow.now.v1";
2274	/* Retired: the passed-plan slot that used to back the "Restore" bar. The key is
2275	 * kept only so restoreNowState can delete whatever an earlier visit left in a
2276	 * returning browser — remove it once no live browser can still be carrying one. */
2277	const LEGACY_STALE_KEY = "edfringenow.now.stale.v1";
2278	/* The first-run explainer's own key, deliberately separate from the settings
2279	 * snapshot above: "I've read this" is a fact about the person, not about this
2280	 * visit's filters, and it must not be cleared when a plan goes stale. */
2281	const INTRO_KEY = "edfringenow.now.intro.v1";
2282	
2283	function readStore(key) {
2284	  try {
2285	    const raw = localStorage.getItem(key);
2286	    return raw ? JSON.parse(raw) : null;
2287	  } catch (err) {
2288	    console.info("EdFringeNow: couldn't read saved settings", err);
2289	    return null;
2290	  }
2291	}
2292	
2293	function writeStore(key, value) {
2294	  try {
2295	    if (value === null) localStorage.removeItem(key);
2296	    else localStorage.setItem(key, JSON.stringify(value));
2297	  } catch (err) {
2298	    // Private browsing / a full quota — the page works fine unsaved.
2299	    console.info("EdFringeNow: couldn't save settings", err);
2300	  }
2301	}
