2699	/* Compass bearing (degrees clockwise from north) from A to B. */
2700	function bearing(a, b) {
2701	  const toRad = (d) => (d * Math.PI) / 180;
2702	  const toDeg = (r) => (r * 180) / Math.PI;
2703	  const y = Math.sin(toRad(b[1] - a[1])) * Math.cos(toRad(b[0]));
2704	  const x =
2705	    Math.cos(toRad(a[0])) * Math.sin(toRad(b[0])) -
2706	    Math.sin(toRad(a[0])) * Math.cos(toRad(b[0])) * Math.cos(toRad(b[1] - a[1]));
