2714	  const dLat = toRad(lat2 - lat1);
2715	  const dLng = toRad(lng2 - lng1);
2716	  const a =
2717	    Math.sin(dLat / 2) ** 2 +
2718	    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
