1	/* Clock helpers for the Now page.
2	 *
3	 * The whole page is scoped to "the next few hours", so what "now" is matters
4	 * more here than anywhere else. Once the app switches off its testing pre-set
5	 * and onto the device's real clock (a confirmed in-UK location does that), that
6	 * clock has to keep moving — these are the bits of the ticker that are pure
7	 * enough to test on their own. Everything else about the tick is DOM work and
8	 * lives in app.js.
9	 *
10	 * Every time the app *shows* is Edinburgh wall-clock: show times arrive that
11	 * way from the scraper (see scraper/normalize.py's local_date_start), and the
12	 * clock they're compared against is read the same way here rather than off the
13	 * device's zone. That's the whole point — a doors-at-19:30 show is 19:30 on
14	 * the page whoever is looking, and "on now" means on now at the venue, not on
15	 * now wherever the phone thinks it is.
16	 */
17	
18	/* The festival's zone. Everything below reads a Date through this by default. */
19	export const FESTIVAL_TZ = "Europe/London";
20	
21	/* Milliseconds from `date` to the very next turn of the minute.
22	 *
23	 * The ticker re-arms with this rather than a flat 60 000 ms so it fires ON the
24	 * minute instead of drifting a little later with every hop — the displayed
25	 * clock changes when the real one does. Exactly on the minute returns a whole
26	 * minute (the next boundary), never 0, so a timer can't spin. */
27	export function msToNextMinute(date) {
28	  const elapsed = date.getSeconds() * 1000 + date.getMilliseconds();
29	  return 60000 - elapsed;
30	}
31	
32	/* An instant read as Edinburgh wall-clock, as the pieces the app displays and
33	 * compares: { date: "2026-08-14", time: "15:44", minutes: 944 } plus the raw
34	 * hour/minute. `minutes` is minutes since local midnight, which is the unit
35	 * every "is it on yet / can I still get there" comparison uses.
36	 *
37	 * `timeZone` is overridable for tests; callers in the app never pass one.
38	 *
39	 * If the environment has no such zone (an ancient browser, a stripped ICU), it
40	 * falls back to the device's own clock — the old behaviour, right in the UK
41	 * and no worse than it was anywhere else. */
42	export function festivalNow(date, timeZone = FESTIVAL_TZ) {
43	  let y, mo, d, h, mi;
44	  try {
45	    const parts = new Intl.DateTimeFormat("en-GB", {
46	      timeZone,
47	      hourCycle: "h23",
48	      year: "numeric",
49	      month: "2-digit",
50	      day: "2-digit",
51	      hour: "2-digit",
52	      minute: "2-digit",
53	    })
54	      .formatToParts(date)
55	      .reduce((acc, p) => ((acc[p.type] = p.value), acc), {});
56	    [y, mo, d, h, mi] = [parts.year, parts.month, parts.day, parts.hour, parts.minute]
57	      .map(Number);
58	    if ([y, mo, d, h, mi].some(Number.isNaN)) throw new Error("unparsable parts");
59	  } catch (err) {
60	    [y, mo, d, h, mi] = [date.getFullYear(), date.getMonth() + 1, date.getDate(),
61	                         date.getHours(), date.getMinutes()];
62	  }
63	  const p2 = (n) => String(n).padStart(2, "0");
64	  return {
65	    year: y, month: mo, day: d, hour: h, minute: mi,
66	    date: `${y}-${p2(mo)}-${p2(d)}`,
67	    time: `${p2(h)}:${p2(mi)}`,
68	    minutes: h * 60 + mi,
69	  };
70	}
71	
72	/* The inverse: the instant whose Edinburgh reading is `local`, given as
