75	 *
76	 * Read the wall-clock as if it were UTC to get a first guess, then correct by
77	 * however far that guess actually lands from the target in Edinburgh. Twice,
78	 * because a guess sitting near a DST boundary can be corrected across it and
79	 * need a second, smaller nudge; the second pass is a no-op the rest of the
80	 * year. Returns an Invalid Date for input a Date can't be made from, which is
81	 * what callers already test for. */
82	export function festivalDate(local, timeZone = FESTIVAL_TZ) {
83	  let guess = new Date(`${local}Z`);
84	  if (isNaN(guess.getTime())) return guess;
85	  const targetMs = Date.parse(`${local}Z`);
86	  for (let pass = 0; pass < 2; pass++) {
87	    const got = festivalNow(guess, timeZone);
88	    const drift = Date.parse(`${got.date}T${got.time}Z`) - targetMs;
89	    if (!drift) break;
90	    guess = new Date(guess.getTime() - drift);
91	  }
92	  return guess;
93	}
94	
95	/* Short name of a time zone at a given moment — "BST" / "GMT" for the UK. The
96	 * label beside the clock; `timeZone` defaults to the device's own zone.
97	 *
98	 * Returns "" if the browser won't say, so callers can keep whatever label they
99	 * were showing rather than blanking it. */
100	export function timeZoneLabel(date, timeZone) {
101	  try {
102	    const opts = { timeZoneName: "short" };
103	    if (timeZone) opts.timeZone = timeZone;
104	    const part = new Intl.DateTimeFormat("en-GB", opts)
105	      .formatToParts(date)
106	      .find((p) => p.type === "timeZoneName");
107	    return part ? part.value : "";
108	  } catch (err) {
109	    return "";
110	  }
111	}
112

1	/* The time wheel's arithmetic — what the "next commitment" picker is allowed to
2	 * offer, and where it opens. Pure functions of "minutes since the start of the
3	 * fringe day", so they're testable without a DOM (see
4	 * js/__tests__/constraint-time.test.mjs).
5	 *
6	 * The rule the whole file serves: the wheel offers everything from now to the
7	 * end of the day and nothing before it. A picker that opens on a time you've
8	 * already missed — or one that skips the next hour because no show happens to
9	 * start in it — reads as broken.
10	 *
11	 * "The end of the day" is the FRINGE day (shared/fringe-day.js), which runs to
12	 * 06:00 the next morning. So late in the evening the hour wheel rolls on past 23
13	 * into the extended hours 24–29, and the times it produces ("24:30") are the
14	 * same extended strings the day file and the rest of the app use. The wheel
15	 * *labels* them 00–05 (js/app.js) — the extension is bookkeeping, not something
16	 * anyone should have to read.
17	 */
18	
19	import { DAY_MINUTES, FRINGE_DAY_END_MINUTES } from "../shared/fringe-day.js";
20	
21	export const WHEEL_STEP = 5; // the wheel's minute granularity
22	export const WHEEL_MINUTES = ["00", "05", "10", "15", "20", "25", "30", "35", "40", "45", "50", "55"];
23	
24	/* The last five-minute slot of the fringe day — 29:55, i.e. 05:55 tomorrow. */
25	const LAST_SLOT = FRINGE_DAY_END_MINUTES - WHEEL_STEP;
26	const LAST_HOUR = Math.floor(LAST_SLOT / 60);
27	
28	/* How far ahead the picker *opens*. Far enough that there's a real choice of
29	 * shows to aim for, near enough to still be part of the same outing. */
30	export const CONSTRAINT_DEFAULT_LEAD_MINUTES = 120;
31	
32	/* The earliest slot the wheel offers: the next whole five minutes from now,
33	 * never past the last slot of the day (so a late-night now still has a wheel). */
34	export function earliestWheelMinutes(nowMinutes) {
35	  return Math.min(Math.ceil(nowMinutes / WHEEL_STEP) * WHEEL_STEP, LAST_SLOT);
36	}
37	
38	/* The hours the wheel offers: the current hour through the end of the fringe
39	 * day, zero-padded. Past midnight these are the extended hours 24–29. */
40	export function wheelHours(nowMinutes) {
41	  const h0 = Math.floor(earliestWheelMinutes(nowMinutes) / 60);
42	  const hours = [];
43	  for (let h = h0; h <= LAST_HOUR; h++) hours.push(String(h).padStart(2, "0"));
44	  return hours;
45	}
46	
47	/* Minutes offered for a given hour. Every hour gets the full set except the
48	 * current one, where the minutes already gone are dropped. */
49	export function minutesForHour(hh, nowMinutes) {
50	  const earliest = earliestWheelMinutes(nowMinutes);
51	  if (parseInt(hh, 10) !== Math.floor(earliest / 60)) return WHEEL_MINUTES;
52	  const floor = earliest % 60;
53	  return WHEEL_MINUTES.filter((m) => +m >= floor);
54	}
55	
56	/* Where the wheel opens when nothing is chosen yet: now + the default lead,
57	 * snapped to the five-minute grid and kept inside the fringe day. */
58	export function defaultConstraintTime(nowMinutes) {
59	  const target =
60	    Math.round((nowMinutes + CONSTRAINT_DEFAULT_LEAD_MINUTES) / WHEEL_STEP) * WHEEL_STEP;
61	  const mins = Math.max(earliestWheelMinutes(nowMinutes), Math.min(target, LAST_SLOT));
62	  return `${String(Math.floor(mins / 60)).padStart(2, "0")}:${String(mins % 60).padStart(2, "0")}`;
63	}
64	
65	/* Re-exported so callers that only talk to the wheel don't have to reach past it
66	 * for the one constant they need. */
67	export { DAY_MINUTES, FRINGE_DAY_END_MINUTES };
68

1	// Main API the UI calls: matching favourites against the show catalogue,
2	// summarizing availability within a date/time window, and (for later use) the
3	// scheduling primitives ported from edfringe/scheduling.py.
4	//
5	// Pure — no DOM, no fetch. The UI is responsible for loading data/normalized/
6	// shows.json and the favourites file text and passing them in.
7	
8	import { urlFromSlug } from "./favourites.js";
9	import {
10	  isAvailable,
11	  isNonTicketed,
12	  dateTimeToMinutes,
13	  timeToMinutesOfDay,
14	} from "./availability.js";
15	import { travelMinutes, DEFAULT_TRAVEL_MODE } from "./travel.js";
16	import { FRINGE_DAY_START_MINUTES, shiftDate } from "../../shared/fringe-day.js";
17	
18	// --- indexing / matching --------------------------------------------------
19	
20	/**
21	 * Index shows by slug for O(1) favourite lookup.
22	 * @param {object[]} shows shows.json array
23	 * @returns {Map<string, object>}
24	 */
25	export function buildIndex(shows) {
26	  const index = new Map();
27	  for (const show of shows || []) {
28	    if (show && show.slug) index.set(show.slug, show);
29	  }
30	  return index;
31	}
32	
33	/**
34	 * Resolve favourite slugs against the show index.
35	 * @param {string[]} slugs de-duplicated slugs from parseFavourites
36	 * @param {Map<string, object>} index from buildIndex
37	 * @returns {{matched: object[], missingSlugs: string[]}}
38	 */
39	export function matchFavourites(slugs, index) {
40	  const matched = [];
41	  const missingSlugs = [];
42	  for (const slug of slugs || []) {
43	    const show = index.get(slug);
44	    if (show) matched.push(show);
45	    else missingSlugs.push(slug);
46	  }
47	  return { matched, missingSlugs };
48	}
49	
50	// --- summarizing availability within a window -----------------------------
51	
52	/**
53	 * Normalize a startTimeMin/Max filter bound to minutes-since-midnight: pass
54	 * through a number as-is, or parse an "HH:MM" string.
55	 * @param {number|string} bound
56	 * @returns {number}
57	 */
58	function normalizeTimeBound(bound) {
59	  if (typeof bound === "number") return bound;
60	  if (typeof bound === "string") return timeToMinutesOfDay(bound);
61	  throw new TypeError(`Expected number or "HH:MM" string, got ${JSON.stringify(bound)}`);
62	}
63	
64	/**
65	 * Annotate every performance of every show against a date/time-of-day window,
66	 * and roll up summary counts.
67	 *
68	 * @param {object[]} shows shows to summarize (typically matchFavourites(...).matched)
69	 * @param {{dateStart: string, dateEnd: string, startTimeMin: number|string, startTimeMax: number|string}} filter
70	 *   dateStart/dateEnd are "YYYY-MM-DD" (inclusive). startTimeMin/startTimeMax are
71	 *   either minutes-since-midnight or "HH:MM" strings (inclusive).
72	 * @param {number} [totalFavourites] total favourite slugs before matching (defaults
73	 *   to shows.length when the caller only has the matched set on hand).
74	 * @returns {{
75	 *   counts: {totalFavourites: number, matchedShows: number, showsAvailableInWindow: number},
76	 *   shows: Array<{
77	 *     slug: string, title: string,
78	 *     performances: Array<{date: string, start: string, available: boolean, status: string|null, soldOut: boolean, inWindow: boolean}>,
79	 *     availableDateSpan: {min: string, max: string} | null,
80	 *   }>,
81	 * }}
82	 */
83	export function summarize(shows, filter, totalFavourites) {
84	  const dateStart = filter.dateStart;
85	  const dateEnd = filter.dateEnd;
86	  const startTimeMin = normalizeTimeBound(filter.startTimeMin);
87	  const startTimeMax = normalizeTimeBound(filter.startTimeMax);
88	
89	  const summarizedShows = (shows || []).map((show) => {
90	    let availableMin = null;
91	    let availableMax = null;
92	    let hasInWindow = false;
93	
94	    const performances = (show.performances || []).map((perf) => {
95	      const available = isAvailable(perf);
96	      if (available) {
97	        if (availableMin === null || perf.date < availableMin) availableMin = perf.date;
98	        if (availableMax === null || perf.date > availableMax) availableMax = perf.date;
99	      }
100	      const dateInRange = perf.date >= dateStart && perf.date <= dateEnd;
101	      const startMinOfDay = timeToMinutesOfDay(perf.start);
102	      const timeInRange = startMinOfDay >= startTimeMin && startMinOfDay <= startTimeMax;
103	      const inWindow = available && dateInRange && timeInRange;
104	      if (inWindow) hasInWindow = true;
105	      return {
106	        date: perf.date,
107	        start: perf.start,
108	        available,
109	        status: perf.status ?? null,
110	        soldOut: !!perf.soldOut,
111	        inWindow,
112	      };
113	    });
114	
115	    return {
116	      slug: show.slug,
117	      title: show.title,
118	      performances,
119	      availableDateSpan: availableMin ? { min: availableMin, max: availableMax } : null,
120	      _hasInWindow: hasInWindow, // internal, stripped before returning below
121	    };
122	  });
123	
124	  const showsAvailableInWindow = summarizedShows.filter((s) => s._hasInWindow).length;
125	  for (const s of summarizedShows) delete s._hasInWindow;
126	
127	  return {
128	    counts: {
129	      totalFavourites: totalFavourites ?? (shows ? shows.length : 0),
130	      matchedShows: shows ? shows.length : 0,
131	      showsAvailableInWindow,
132	    },
133	    shows: summarizedShows,
134	  };
135	}
136	
137	// --- scheduling primitives (for later use) ---------------------------------
138	// Ported from edfringe/scheduling.py. Default trip window and gap match the
139	// Python module's defaults for 2026; all are overridable parameters here
140	// rather than module-level globals (Python's `configure()`).
141	
142	export const DEFAULT_WINDOW_START = "2026-08-07T15:00";
143	export const DEFAULT_WINDOW_END = "2026-08-24T17:00";
144	export const DEFAULT_MIN_GAP_SAME_VENUE = 0;
145	export const DEFAULT_MIN_GAP_DIFFERENT_VENUE = 30;
146	
147	// A Fringe evening runs past midnight: a performance that starts before this
148	// clock time belongs to the PREVIOUS calendar day's festival night, drawn near
149	// the top of that day's 09:00–27:00 schedule column rather than at the bottom of
150	// its own morning. Folding adds 1440 to its minute-of-day (so 00:45 → 24:45) and
151	// re-dates it to the night before.
152	//
153	// The cutoff is the one the whole site cuts its days at (06:00 —
154	// shared/fringe-day.js), not a number of the planner's own: the Now page buckets
155	// its day files by it and the scraper writes them by it, and a planner that
156	// disagreed would place the same late show on a different night from the page
157	// beside it. Safe either way — nothing in the catalogue starts between 00:30
158	// and 06:00.
159	export const NIGHT_FOLD_CUTOFF_MIN = FRINGE_DAY_START_MINUTES;
160	
161	/** Previous calendar day for a "YYYY-MM-DD" string (deterministic, no clock). */
162	function previousDate(dateISO) {
163	  return shiftDate(dateISO, -1);
164	}
165	
166	/**
167	 * A performance's "festival night" placement. A show starting after midnight is
168	 * folded onto the previous evening: same real wall-clock start/end (kept for
169	 * exports and chronological ordering), but a festival date one day earlier and a
170	 * minute-of-day past 24:00 so it lands at the top of that night's column.
171	 * @param {string} date real "YYYY-MM-DD"
172	 * @param {number} startMinuteOfDay real minutes-since-midnight of the start
173	 * @param {number} cutoffMin fold shows starting before this clock minute
174	 * @returns {{festivalDate: string, festivalStartMinute: number}}
175	 */
176	export function festivalNight(date, startMinuteOfDay, cutoffMin = NIGHT_FOLD_CUTOFF_MIN) {
177	  if (startMinuteOfDay < cutoffMin) {
178	    return { festivalDate: previousDate(date), festivalStartMinute: startMinuteOfDay + 1440 };
179	  }
180	  return { festivalDate: date, festivalStartMinute: startMinuteOfDay };
181	}
182	
183	/**
184	 * Parse a "YYYY-MM-DDTHH:MM" (or Date) into minutes-since-epoch, consistent
185	 * with availability.js's wall-clock minute counting.
186	 * @param {string|Date} value
187	 * @returns {number}
188	 */
189	function toMinutes(value) {
190	  if (value instanceof Date) return value.getTime() / 60000;
191	  const [date, time] = value.split("T");
192	  return dateTimeToMinutes(date, time || "00:00");
193	}
194	
195	/**
196	 * One bookable performance of a show, eligible for scheduling. Mirrors
197	 * scheduling.py's Slot dataclass, adapted to shows.json's fields (venueCode
198	 * from `show.venue`, no separate various-venue flag in this dataset).
199	 * @typedef {object} Slot
200	 * @property {string} slug
201	 * @property {string} title
202	 * @property {string|null} genre
203	 * @property {string} date
204	 * @property {string} startTime "HH:MM"
205	 * @property {number} start minutes since epoch
206	 * @property {number} end minutes since epoch
207	 * @property {number} startMinuteOfDay minutes-since-midnight of the start
208	 * @property {number} endMinuteOfDay minutes-since-midnight of the end (capped at
209	 *   1440 for a performance that runs past midnight)
210	 * @property {string|null} status raw ticketStatus from shows.json (for display/colour)
211	 * @property {string|null} venueCode
212	 * @property {string|null} venueName
213	 * @property {number|null} venueLat
214	 * @property {number|null} venueLng
215	 * @property {string|null} room
216	 * @property {string|null} image
217	 * @property {string|null} blurb
218	 * @property {number|null} duration minutes
219	 * @property {string} url
220	 * @property {boolean} freeNonTicketed
221	 */
222	
223	/** Resolve a venue code to {lat,lng} from a coords lookup (a Map or a plain
224	 *  object keyed by venue code), or null when unknown / an online venue. */
225	function lookupVenueCoord(venueCoords, code) {
226	  if (!venueCoords || code == null) return null;
227	  const key = String(code);
228	  const v = venueCoords instanceof Map ? venueCoords.get(key) : venueCoords[key];
229	  if (!v || v.lat == null || v.lng == null) return null;
230	  return { lat: v.lat, lng: v.lng };
231	}
232	
233	/**
234	 * Per-show available performances that fit entirely inside the trip window.
235	 * Mirrors scheduling.py's `eligible_slots` (window + availability filter only
236	 * — gap/overlap compatibility and the day-hours/meal-break filter are separate
237	 * concerns, see `compatible` / `withinDayWindow`).
238	 *
239	 * @param {object[]} shows
240	 * @param {{windowStart?: string|Date, windowEnd?: string|Date,
241	 *          venueCoords?: Map<string,{lat:number,lng:number}>|object}} [options]
242	 *   venueCoords lets slots carry venue lat/lng so the scheduler can size
243	 *   different-venue gaps by real travel time and the UI can draw travel legs.
244	 * @returns {Map<string, Slot[]>}
245	 */
246	export function eligibleSlots(shows, options = {}) {
247	  const windowStart = toMinutes(options.windowStart ?? DEFAULT_WINDOW_START);
248	  const windowEnd = toMinutes(options.windowEnd ?? DEFAULT_WINDOW_END);
249	  const venueCoords = options.venueCoords ?? null;
250	  const cutoff = options.nightCutoffMin ?? NIGHT_FOLD_CUTOFF_MIN;
251	  // When date bounds are given, membership is by *festival* date (so a Friday
252	  // 00:45 late show counts as Friday night, and a show on the morning after the
253	  // last day does not leak in). Otherwise fall back to the epoch window filter.
254	  const byFestivalDate = options.dateStart != null && options.dateEnd != null;
255	
256	  const out = new Map();
257	  for (const show of shows || []) {
258	    const coord = lookupVenueCoord(venueCoords, show.venue);
259	    const dur = show.duration || 0;
260	    const slots = [];
261	    for (const perf of show.performances || []) {
262	      if (!isAvailable(perf)) continue;
263	      const start = dateTimeToMinutes(perf.date, perf.start);
264	      const end = show.duration ? start + show.duration : start;
265	      const realStartMinute = timeToMinutesOfDay(perf.start);
266	      // Fold an after-midnight start onto the previous festival night: real
267	      // date/epoch are preserved (for exports + ordering) while the display
268	      // date and minute-of-day move to the night before.
269	      const { festivalDate, festivalStartMinute } = festivalNight(perf.date, realStartMinute, cutoff);
270	      if (byFestivalDate) {
271	        if (festivalDate < options.dateStart || festivalDate > options.dateEnd) continue;
272	      } else if (start < windowStart || end > windowEnd) {
273	        continue;
274	      }
275	      const startMinuteOfDay = festivalStartMinute;
276	      // The end-of-day is no longer capped at 24:00 — an evening show that runs
277	      // past midnight keeps its true length so the day-hours test and the
278	      // 09:00–27:00 axis can place and draw it honestly.
279	      const endMinuteOfDay = startMinuteOfDay + dur;
280	      slots.push({
281	        slug: show.slug,
282	        title: show.title,
283	        genre: show.genre ?? null,
284	        date: festivalDate,
285	        realDate: perf.date,
286	        startTime: perf.start,
287	        start,
288	        end,
289	        startMinuteOfDay,
290	        endMinuteOfDay,
291	        status: perf.status ?? null,
292	        venueCode: show.venue ?? null,
293	        venueName: show.venueName ?? null,
294	        venueLat: coord ? coord.lat : null,
295	        venueLng: coord ? coord.lng : null,
296	        room: show.room ?? null,
297	        image: show.image ?? show.smallImage ?? null,
298	        blurb: show.blurb ?? null,
299	        duration: show.duration ?? null,
300	        url: urlFromSlug(show.slug),
301	        freeNonTicketed: isNonTicketed(perf),
302	      });
303	    }
304	    slots.sort((a, b) => a.start - b.start || a.end - b.end);
305	    out.set(show.slug, slots);
306	  }
307	  return out;
308	}
309	
310	/**
311	 * Stable identity for one performance within a show: its real date + start time
312	 * ("YYYY-MM-DDTHH:MM"). The UI builds the same key from a favourite's raw
313	 * performance (date + start) so a "pin this exact performance" request lines up
314	 * with the slot the scheduler sees — one source of truth for both sides.
315	 * @param {{realDate?: string, date?: string, startTime?: string, start?: string}} p
316	 * @returns {string}
317	 */
318	export function slotKey(p) {
319	  const date = p.realDate ?? p.date;
320	  const start = p.startTime ?? p.start;
321	  return `${date}T${start}`;
322	}
323	
324	/**
325	 * Normalize meal-break specs into `{startMin, endMin}` minute-of-day ranges,
326	 * dropping ones that are disabled (`enabled === false`), malformed, or
327	 * zero/negative length. Accepts `{startMin, endMin}` numbers or `{start, end}`
328	 * "HH:MM" strings.
329	 * @param {Array<{startMin?:number,endMin?:number,start?:string,end?:string,enabled?:boolean}>} breaks
330	 * @returns {Array<{startMin:number, endMin:number}>}
331	 */
332	export function normalizeMealBreaks(breaks) {
333	  if (!Array.isArray(breaks)) return [];
334	  const out = [];
335	  for (const b of breaks) {
336	    if (!b || b.enabled === false) continue;
337	    const startMin = b.startMin ?? (b.start != null ? timeToMinutesOfDay(b.start) : null);
338	    const endMin = b.endMin ?? (b.end != null ? timeToMinutesOfDay(b.end) : null);
339	    if (startMin == null || endMin == null || endMin <= startMin) continue;
340	    out.push({ startMin, endMin });
341	  }
342	  return out;
343	}
344	
345	/**
346	 * True if a slot starts no earlier than the day start, ends no later than the
347	 * day end, and overlaps none of the meal breaks — the day-hours filter the
348	 * scheduler applies before allocating.
349	 * @param {Slot} slot
350	 * @param {{dayStartMin?:number, dayEndMin?:number, mealBreaks?:Array<{startMin:number,endMin:number}>}} [win]
351	 * @returns {boolean}
352	 */
353	export function withinDayWindow(slot, win = {}) {
354	  const dayStartMin = win.dayStartMin ?? 0;
355	  const dayEndMin = win.dayEndMin ?? 1440;
356	  if (slot.startMinuteOfDay < dayStartMin) return false;
357	  if (slot.endMinuteOfDay > dayEndMin) return false;
358	  for (const b of win.mealBreaks || []) {
359	    // Overlap (half-open): a show touching a break edge-to-edge is fine.
360	    if (slot.startMinuteOfDay < b.endMin && slot.endMinuteOfDay > b.startMin) return false;
361	  }
362	  return true;
363	}
364	
365	/**
366	 * Minutes required between two slots. Same known venue → the same-venue buffer
367	 * (a double bill needs no travel). Different venues → the greater of the
368	 * different-venue buffer (a floor, also the value used when coordinates are
369	 * unknown) and the estimated door-to-door travel time by the chosen mode, so
370	 * the gap grows with distance and shrinks on a bike/car. Extends
371	 * scheduling.py's `required_gap_minutes` with the travel estimate.
372	 * @param {Slot} a
373	 * @param {Slot} b
374	 * @param {{minGapSameVenue?: number, minGapDifferentVenue?: number, travelMode?: string}} [options]
375	 * @returns {number}
376	 */
377	export function requiredGapMinutes(a, b, options = {}) {
378	  const minGapSameVenue = options.minGapSameVenue ?? DEFAULT_MIN_GAP_SAME_VENUE;
379	  const minGapDifferentVenue = options.minGapDifferentVenue ?? DEFAULT_MIN_GAP_DIFFERENT_VENUE;
380	  if (a.venueCode && b.venueCode && a.venueCode === b.venueCode) {
381	    return minGapSameVenue;
382	  }
383	  const t = travelMinutes(
384	    { lat: a.venueLat, lng: a.venueLng },
385	    { lat: b.venueLat, lng: b.venueLng },
386	    options.travelMode ?? DEFAULT_TRAVEL_MODE
387	  );
388	  if (t == null) return minGapDifferentVenue; // unknown coords — fall back to the flat buffer
389	  return Math.max(minGapDifferentVenue, Math.ceil(t));
390	}
391	
392	/**
393	 * True if both performances can be attended: no overlap, and at least the
394	 * required travel-buffer gap between them. Mirrors scheduling.py's `compatible`.
395	 * @param {Slot} a
396	 * @param {Slot} b
397	 * @param {{minGapSameVenue?: number, minGapDifferentVenue?: number}} [options]
398	 * @returns {boolean}
399	 */
400	export function compatible(a, b, options = {}) {
401	  const [earlier, later] = a.start <= b.start ? [a, b] : [b, a];
402	  return later.start >= earlier.end + requiredGapMinutes(earlier, later, options);
403	}
404	
405	// --- building an itinerary from the eligible slots ------------------------
406	
407	/**
408	 * Greedily allocate a conflict-free itinerary: at most one performance per
409	 * show, no two performances on the same day overlapping (or closer than the
410	 * required travel gap), at most `maxPerDay` shows on any one day, and only
411	 * performances that fall within the day-hours window and miss the meal breaks.
412	 *
413	 * The heuristic is classic earliest-finish-first activity selection — the
414	 * optimal greedy for "fit the most non-overlapping intervals on one machine" —
415	 * extended for this domain: once a show is placed, its other performances are
416	 * skipped (one-per-show), and a candidate is dropped if its day is already at
417	 * the per-day cap. Ties break deterministically (earliest start, then slug),
418	 * so the same inputs always yield the same plan — no wall-clock/random state.
419	 *
420	 * `forcedSlugs` are must-see shows placed in a first pass before the greedy
421	 * fill: each takes its earliest-finishing performance that doesn't clash with
422	 * another forced show, ignoring the per-day cap. The greedy pass then fills
423	 * around them, and the min-per-day post-pass never drops a day that holds a
424	 * forced show.
425	 *
426	 * `forcedPerformances` pins a must-see to one *specific* performance (keyed by
427	 * `slotKey`, "YYYY-MM-DDTHH:MM") rather than letting pass 1 pick. A pinned slug
428	 * is forced automatically (no need to also list it in `forcedSlugs`), and its
429	 * chosen performance is honoured even if the day-hours window or a meal break
430	 * would otherwise filter it out — the user asked for exactly this one. It can
431	 * still be displaced only by a hard clash with another must-see.
432	 *
433	 * `minPerDay` is applied as a post-pass: a day holding fewer than the minimum
434	 * (and no forced show) is dropped whole (you don't trek into town for a single
435	 * show), and its shows fall back to `unscheduled` with a "below your minimum"
436	 * reason. Leave it at 1 (the default) to keep every day.
437	 *
438	 * @param {object[]} shows shows to schedule (typically matchFavourites(...).matched)
439	 * @param {{
440	 *   windowStart?: string|Date, windowEnd?: string|Date,
441	 *   minGapSameVenue?: number, minGapDifferentVenue?: number,
442	 *   travelMode?: string, venueCoords?: Map<string,{lat:number,lng:number}>|object,
443	 *   dayStartMin?: number, dayEndMin?: number,
444	 *   mealBreaks?: Array<{startMin?:number,endMin?:number,start?:string,end?:string,enabled?:boolean}>,
445	 *   maxPerDay?: number, minPerDay?: number, forcedSlugs?: string[]|Set<string>,
446	 *   forcedPerformances?: Map<string,string>|Object<string,string>,
447	 * }} [options]
448	 * @returns {{
449	 *   days: Array<{date: string, slots: Slot[]}>,
450	 *   scheduled: Slot[],
451	 *   unscheduled: Array<{slug: string, title: string, reason: string}>,
452	 *   forced: string[],
453	 *   counts: {matchedShows: number, scheduledShows: number, days: number},
454	 * }}
455	 */
456	export function buildSchedule(shows, options = {}) {
457	  const windowStart = options.windowStart ?? DEFAULT_WINDOW_START;
458	  const windowEnd = options.windowEnd ?? DEFAULT_WINDOW_END;
459	  const gapOpts = {
460	    minGapSameVenue: options.minGapSameVenue ?? DEFAULT_MIN_GAP_SAME_VENUE,
461	    minGapDifferentVenue: options.minGapDifferentVenue ?? DEFAULT_MIN_GAP_DIFFERENT_VENUE,
462	    travelMode: options.travelMode ?? DEFAULT_TRAVEL_MODE,
463	  };
464	  const maxPerDay = options.maxPerDay ?? Infinity;
465	  const minPerDay = options.minPerDay ?? 1;
466	  const dayWindow = {
467	    dayStartMin: options.dayStartMin ?? 0,
468	    dayEndMin: options.dayEndMin ?? 1440,
469	    mealBreaks: normalizeMealBreaks(options.mealBreaks),
470	  };
471	  // Pinned-to-a-specific-performance must-sees (slug -> slotKey). A pinned slug
472	  // is forced too, so fold its keys into forcedSlugs.
473	  const forcedPerformances =
474	    options.forcedPerformances instanceof Map
475	      ? new Map(options.forcedPerformances)
476	      : new Map(Object.entries(options.forcedPerformances ?? {}));
477	  const forcedSlugs = new Set(options.forcedSlugs ?? []);
478	  for (const slug of forcedPerformances.keys()) forcedSlugs.add(slug);
479	
480	  // Every window+availability slot (with coords + minute-of-day annotations)…
481	  const slotsByShowAll = eligibleSlots(shows, {
482	    windowStart,
483	    windowEnd,
484	    dateStart: options.dateStart,
485	    dateEnd: options.dateEnd,
486	    venueCoords: options.venueCoords ?? null,
487	  });
488	  // …then narrowed to those inside the day-hours window and clear of meal
489	  // breaks. `lostToDayWindow` remembers shows that had window slots but lost
490	  // them all to that filter, for an honest unscheduled reason.
491	  // Optional per-date "getting there" / "getting out" blocks. On the arrival
492	  // date the block *replaces* the day-start, so day one can begin earlier (or
493	  // later) than the rest of the trip: nothing starts before `arrival.endMin`.
494	  // On the departure date it replaces the day-end: nothing runs past
495	  // `departure.startMin`. Modelled as date-specific meal breaks so they ride the
496	  // same day-window filter (and, like meal breaks, an explicit performance pin
497	  // still overrides them via slotsByShowAll).
498	  const arrival = options.arrival && options.arrival.endMin != null ? options.arrival : null;
499	  const departure = options.departure && options.departure.startMin != null ? options.departure : null;
500	  const windowForDate = (date) => {
501	    const isArrival = arrival && arrival.date === date;
502	    const isDeparture = departure && departure.date === date;
503	    if (!isArrival && !isDeparture) return dayWindow;
504	    const w = { ...dayWindow, mealBreaks: dayWindow.mealBreaks.slice() };
505	    if (isArrival) {
506	      w.dayStartMin = 0; // the getting-there block owns day one's start
507	      w.mealBreaks.push({ startMin: 0, endMin: arrival.endMin });
508	    }
509	    if (isDeparture) {
510	      w.dayEndMin = Infinity; // the getting-out block owns the last day's end
511	      w.mealBreaks.push({ startMin: departure.startMin, endMin: Infinity });
512	    }
513	    return w;
514	  };
515	  const slotsByShow = new Map();
516	  for (const [slug, slots] of slotsByShowAll) {
517	    slotsByShow.set(slug, slots.filter((s) => withinDayWindow(s, windowForDate(s.date))));
518	  }
519	
520	  const chosen = [];
521	  const placedShows = new Set();
522	  const forcedPlaced = new Set();
523	  const perDay = new Map(); // date -> Slot[] placed that day
524	
525	  const place = (slot, isForced) => {
526	    chosen.push(slot);
527	    placedShows.add(slot.slug);
528	    if (isForced) forcedPlaced.add(slot.slug);
529	    const day = perDay.get(slot.date) || [];
530	    day.push(slot);
531	    perDay.set(slot.date, day);
532	  };
533	
534	  // --- Pass 1: forced (must-see) shows claim their slot first --------------
535	  // Stable slug order so the plan is reproducible. Each forced show takes the
536	  // earliest-finishing performance compatible with the forced shows already
537	  // placed; it ignores the per-day cap (you insisted on it) but still can't
538	  // overlap another must-see.
539	  for (const slug of [...forcedSlugs].sort()) {
540	    const pinnedKey = forcedPerformances.get(slug);
541	    let slots;
542	    if (pinnedKey) {
543	      // Pinned to one exact performance: take it straight from the full window
544	      // set (pre day-hours filter) so an explicit pin overrides day hours and
545	      // meal breaks. Only a hard must-see clash can still bump it.
546	      const match = (slotsByShowAll.get(slug) || []).find((s) => slotKey(s) === pinnedKey);
547	      slots = match ? [match] : [];
548	    } else {
549	      // Whole show forced: prefer a performance that fits the day-hours window
550	      // and dodges meal breaks, but a must-see must still land — so fall back to
551	      // any in-window performance, overriding those blocks (the same override an
552	      // explicit performance pin gets). Unblocked slots are tried first, then
553	      // blocked ones, each group earliest-finishing.
554	      const byEnd = (a, b) => a.end - b.end || a.start - b.start;
555	      const unblocked = [...(slotsByShow.get(slug) || [])].sort(byEnd);
556	      const unblockedKeys = new Set(unblocked.map(slotKey));
557	      const blocked = [...(slotsByShowAll.get(slug) || [])]
558	        .filter((s) => !unblockedKeys.has(slotKey(s)))
559	        .sort(byEnd);
560	      slots = [...unblocked, ...blocked];
561	    }
562	    for (const slot of slots) {
563	      const sameDay = perDay.get(slot.date) || [];
564	      if (sameDay.every((c) => compatible(c, slot, gapOpts))) {
565	        place(slot, true);
566	        break;
567	      }
568	    }
569	  }
570	
571	  // --- Pass 2: greedy earliest-finish for everything else ------------------
572	  const candidates = [];
573	  for (const [slug, slots] of slotsByShow) {
574	    if (forcedSlugs.has(slug)) continue; // handled in pass 1
575	    for (const slot of slots) candidates.push(slot);
576	  }
577	  candidates.sort(
578	    (a, b) =>
579	      a.end - b.end ||
580	      a.start - b.start ||
581	      a.slug.localeCompare(b.slug) ||
582	      a.date.localeCompare(b.date)
583	  );
584	  for (const slot of candidates) {
585	    if (placedShows.has(slot.slug)) continue; // one performance per show
586	    const sameDay = perDay.get(slot.date) || [];
587	    if (sameDay.length >= maxPerDay) continue; // day already full
588	    if (!sameDay.every((c) => compatible(c, slot, gapOpts))) continue; // clash
589	    place(slot, false);
590	  }
591	
592	  // Post-pass: drop under-populated days (min-per-day preference), but never a
593	  // day that holds a forced show.
594	  const droppedShows = new Set();
595	  for (const [date, slots] of perDay) {
596	    if (slots.length >= minPerDay) continue;
597	    if (slots.some((s) => forcedPlaced.has(s.slug))) continue;
598	    for (const slot of slots) droppedShows.add(slot.slug);
599	    perDay.delete(date);
600	  }
601	
602	  const days = [...perDay.entries()]
603	    .map(([date, slots]) => ({
604	      date,
605	      slots: [...slots].sort((a, b) => a.start - b.start || a.end - b.end),
606	    }))
607	    .sort((a, b) => a.date.localeCompare(b.date));
608	
609	  const scheduled = days.flatMap((d) => d.slots);
610	  const scheduledSlugs = new Set(scheduled.map((s) => s.slug));
611	
612	  const unscheduled = [];
613	  for (const show of shows || []) {
614	    if (scheduledSlugs.has(show.slug)) continue;
615	    const windowSlots = (slotsByShowAll.get(show.slug) || []).length;
616	    const daySlots = (slotsByShow.get(show.slug) || []).length;
617	    // A pinned show overrides the day-hours filter, so if its exact performance
618	    // exists in the window yet didn't place, the cause is a must-see clash — not
619	    // a day-hours problem, even when the day-filtered pool is empty.
620	    const pinnedInWindow =
621	      forcedPerformances.has(show.slug) &&
622	      windowSlots > 0 &&
623	      (slotsByShowAll.get(show.slug) || []).some((s) => slotKey(s) === forcedPerformances.get(show.slug));
624	    let reason;
625	    if (windowSlots === 0) reason = "no available performance in your dates";
626	    else if (pinnedInWindow) reason = "forced, but it clashes with another must-see";
627	    else if (daySlots === 0) reason = "only runs outside your day hours or meal breaks";
628	    else if (droppedShows.has(show.slug)) reason = "on a day below your minimum";
629	    else if (forcedSlugs.has(show.slug)) reason = "forced, but it clashes with another must-see";
630	    else reason = "clashes with shows already in your plan";
631	    unscheduled.push({ slug: show.slug, title: show.title, reason });
632	  }
633	
634	  return {
635	    days,
636	    scheduled,
637	    unscheduled,
638	    forced: [...forcedPlaced],
639	    counts: {
640	      matchedShows: (shows || []).length,
641	      scheduledShows: scheduled.length,
642	      days: days.length,
643	    },
644	  };
645	}
646	
647	/**
648	 * Which day-hours / meal-break / trip-block controls are, on their own, making
649	 * a show un-placeable. A show counts as blocked when it has at least one
650	 * available performance inside the date window but none survive the day-hours
651	 * + meal + arrival/departure filter. For each such show we attribute blame to
652	 * every control that would — on its own, all others left as-is — rescue at
653	 * least one performance if relaxed. So a control's list is exactly "the shows
654	 * this control shuts out", ready for a "prevents N shows" label + tooltip and
655	 * an at-a-glance grid mark.
656	 *
657	 * @param {object[]} shows shows to diagnose (typically the matched favourites)
658	 * @param {{
659	 *   dateStart: string, dateEnd: string,
660	 *   dayStartMin?: number, dayEndMin?: number, dayEndCeil?: number,
661	 *   mealBreaks?: Array<{id?:string, startMin?:number, endMin?:number, start?:string, end?:string, enabled?:boolean}>,
662	 *   arrival?: {date:string, endMin:number}|null,
663	 *   departure?: {date:string, startMin:number}|null,
664	 *   venueCoords?: Map<string,{lat:number,lng:number}>|object,
665	 * }} options
666	 * @returns {{
667	 *   blockedSlugs: Set<string>,
668	 *   dayStart: Array<{slug:string,title:string}>,
669	 *   dayEnd: Array<{slug:string,title:string}>,
670	 *   meals: Object<string, Array<{slug:string,title:string}>>,
671	 *   arrival: Array<{slug:string,title:string}>,
672	 *   departure: Array<{slug:string,title:string}>,
673	 * }}
674	 */
675	export function placementDiagnostics(shows, options = {}) {
676	  const dayStartMin = options.dayStartMin ?? 0;
677	  const dayEndMin = options.dayEndMin ?? 1440;
678	  const dayEndCeil = options.dayEndCeil ?? 1620; // 27:00 — the axis' late edge
679	  // Enabled meal breaks, keeping their ids for per-control attribution.
680	  const meals = (options.mealBreaks || [])
681	    .filter((m) => m && m.enabled !== false)
682	    .map((m) => ({
683	      id: m.id || "meal",
684	      startMin: m.startMin ?? (m.start != null ? timeToMinutesOfDay(m.start) : null),
685	      endMin: m.endMin ?? (m.end != null ? timeToMinutesOfDay(m.end) : null),
686	    }))
687	    .filter((m) => m.startMin != null && m.endMin != null && m.endMin > m.startMin);
688	  const arrival = options.arrival && options.arrival.endMin != null ? options.arrival : null;
689	  const departure = options.departure && options.departure.startMin != null ? options.departure : null;
690	
691	  // Whether a slot survives the day-hours filter under a partial relaxation.
692	  // The trip blocks bite only on their own date and own that date's boundary
693	  // outright, exactly as buildSchedule models them: the getting-there block
694	  // replaces day-start on the arrival date, the getting-out block replaces
695	  // day-end on the departure date.
696	  const fits = (slot, ov = {}) => {
697	    let startMin = ov.dayStartMin ?? dayStartMin;
698	    let endMin = ov.dayEndMin ?? dayEndMin;
699	    let breaks = ov.mealBreaks ?? meals;
700	    const arr = "arrival" in ov ? ov.arrival : arrival;
701	    const dep = "departure" in ov ? ov.departure : departure;
702	    if (arr && slot.date === arr.date) {
703	      startMin = 0;
704	      breaks = [...breaks, { startMin: 0, endMin: arr.endMin }];
705	    }
706	    if (dep && slot.date === dep.date) {
707	      endMin = Infinity;
708	      breaks = [...breaks, { startMin: dep.startMin, endMin: Infinity }];
709	    }
710	    return withinDayWindow(slot, { dayStartMin: startMin, dayEndMin: endMin, mealBreaks: breaks });
711	  };
712	
713	  const slotsByShow = eligibleSlots(shows, {
714	    dateStart: options.dateStart,
715	    dateEnd: options.dateEnd,
716	    venueCoords: options.venueCoords ?? null,
717	  });
718	
719	  const result = { blockedSlugs: new Set(), dayStart: [], dayEnd: [], meals: {}, arrival: [], departure: [] };
720	  for (const m of meals) result.meals[m.id] = [];
721	
722	  for (const show of shows || []) {
723	    const slots = slotsByShow.get(show.slug) || [];
724	    if (slots.length === 0) continue; // nothing in the date window — a dates problem, not a day-hours one
725	    if (slots.some((s) => fits(s))) continue; // already placeable
726	    result.blockedSlugs.add(show.slug);
727	    const entry = { slug: show.slug, title: show.title };
728	
729	    // A control is culpable if relaxing only it would let a performance back in.
730	    if (slots.some((s) => fits(s, { dayStartMin: 0 }))) {
731	      result.dayStart.push(entry);
732	    }
733	    if (slots.some((s) => fits(s, { dayEndMin: dayEndCeil }))) {
734	      result.dayEnd.push(entry);
735	    }
736	    for (const m of meals) {
737	      const without = meals.filter((x) => x.id !== m.id);
738	      if (slots.some((s) => fits(s, { mealBreaks: without }))) {
739	        result.meals[m.id].push(entry);
740	      }
741	    }
742	    if (arrival && slots.some((s) => fits(s, { arrival: null }))) {
743	      result.arrival.push(entry);
744	    }
745	    if (departure && slots.some((s) => fits(s, { departure: null }))) {
746	      result.departure.push(entry);
747	    }
748	  }
749	  return result;
750	}
