1	// Turning a built schedule (buildSchedule(...).scheduled — a flat, time-ordered
2	// Slot[]) into the two downloadable artefacts the planner offers:
3	//   - a CSV itinerary (open in a spreadsheet / print)
4	//   - an ICS calendar feed (import into Google/Apple/Outlook)
5	//
6	// Pure — no DOM, no Blob, no clock. The UI layer builds the Blob and passes the
7	// current time into toIcs (for DTSTAMP), so this stays deterministic and unit
8	// -testable.
9	
10	// Slots carry `start`/`end` as minutes-since-epoch counted with Date.UTC (see
11	// availability.js dateTimeToMinutes — a wall-clock count, not a real instant).
12	// We read them back with the matching getUTC* accessors to recover the original
13	// Edinburgh wall-clock date/time with no timezone drift.
14	
15	const pad2 = (n) => String(n).padStart(2, "0");
16	
17	/** A slot's minutes-since-epoch → {date:"YYYY-MM-DD", time:"HH:MM", ...parts}. */
18	function wallClock(epochMinutes) {
19	  const d = new Date(epochMinutes * 60000);
20	  return {
21	    y: d.getUTCFullYear(),
22	    mo: d.getUTCMonth() + 1,
23	    d: d.getUTCDate(),
24	    h: d.getUTCHours(),
25	    mi: d.getUTCMinutes(),
26	    date: `${d.getUTCFullYear()}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}`,
27	    time: `${pad2(d.getUTCHours())}:${pad2(d.getUTCMinutes())}`,
28	  };
29	}
30	
31	/** "HH:MM" end time of a slot (start + duration), for display/CSV. */
32	export function slotEndTime(slot) {
33	  return wallClock(slot.end).time;
34	}
35	
36	// --- CSV -----------------------------------------------------------------
37	
38	/** RFC-4180 field escaping: wrap in quotes and double any embedded quote when
39	 *  the value contains a comma, quote, or newline. */
40	function csvField(value) {
41	  const s = value == null ? "" : String(value);
42	  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
43	}
44	
45	const CSV_HEADERS = ["Date", "Day", "Start", "End", "Show", "Genre", "Venue", "Room", "Status", "Tickets"];
46	
47	// Short weekday for the CSV "Day" column, derived from the wall-clock date.
48	const DOW = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
49	
50	/**
51	 * A CSV itinerary, one row per scheduled performance in the given order.
52	 * @param {import("./engine.js").Slot[]} slots buildSchedule(...).scheduled
53	 * @returns {string} CSV text (CRLF line endings, header row first)
54	 */
55	export function toCsv(slots) {
56	  const rows = [CSV_HEADERS.join(",")];
57	  for (const slot of slots || []) {
58	    const start = wallClock(slot.start);
59	    const dow = DOW[new Date(slot.start * 60000).getUTCDay()];
60	    rows.push(
61	      [
62	        start.date,
63	        dow,
64	        start.time,
65	        slotEndTime(slot),
66	        slot.title,
67	        slot.genre || "",
68	        slot.venueName || slot.venueCode || "",
69	        slot.room || "",
70	        slot.freeNonTicketed ? "Free (non-ticketed)" : "Ticketed",
71	        slot.url || "",
72	      ]
73	        .map(csvField)
74	        .join(",")
75	    );
76	  }
77	  return rows.join("\r\n");
78	}
79	
80	// --- ICS -----------------------------------------------------------------
81	
82	/** ICS local date-time (floating, no timezone) "YYYYMMDDTHHMMSS". These are
83	 *  Edinburgh wall-clock times; floating time keeps them at the same clock face
84	 *  whatever timezone the importing calendar is in — right for an on-the-ground
85	 *  festival plan. */
86	function icsLocal(epochMinutes) {
87	  const w = wallClock(epochMinutes);
88	  return `${w.y}${pad2(w.mo)}${pad2(w.d)}T${pad2(w.h)}${pad2(w.mi)}00`;
89	}
90	
91	/** UTC stamp "YYYYMMDDTHHMMSSZ" for DTSTAMP, from a real Date (export time). */
92	function icsStamp(date) {
93	  return (
94	    `${date.getUTCFullYear()}${pad2(date.getUTCMonth() + 1)}${pad2(date.getUTCDate())}` +
95	    `T${pad2(date.getUTCHours())}${pad2(date.getUTCMinutes())}${pad2(date.getUTCSeconds())}Z`
96	  );
97	}
98	
99	/** Escape a text value for an ICS property (RFC-5545 §3.3.11). */
100	function icsText(value) {
101	  return String(value == null ? "" : value)
102	    .replace(/\\/g, "\\\\")
103	    .replace(/;/g, "\\;")
104	    .replace(/,/g, "\\,")
105	    .replace(/\r?\n/g, "\\n");
106	}
107	
108	/** Fold a content line to ≤75 octets with CRLF + single-space continuations
109	 *  (RFC-5545 §3.1). Counts UTF-8 bytes so multibyte titles fold correctly; a
110	 *  continuation line's leading space counts toward its 75, so those cap at 74
111	 *  characters of payload. */
112	const utf8Len = (s) => new TextEncoder().encode(s).length;
113	function foldLine(line) {
114	  if (utf8Len(line) <= 75) return line;
115	  const out = [];
116	  let chunk = "";
117	  let cap = 75; // first line gets the full 75; continuations lose 1 to the space
118	  for (const ch of line) {
119	    if (utf8Len(chunk + ch) > cap) {
120	      out.push(chunk);
121	      chunk = "";
122	      cap = 74;
123	    }
124	    chunk += ch;
125	  }
126	  out.push(chunk);
127	  return out.join("\r\n ");
128	}
129	
130	/* The festival's timezone, shipped inside the file.
131	 *
132	 * Times used to go out "floating" (no zone at all), which every calendar app is
133	 * entitled to read as the *importing user's* local time — so a visitor whose
134	 * Google Calendar is set to New York imported an Edinburgh plan five hours out.
135	 * Naming Europe/London and defining it here removes the guess: the events land
136	 * at Edinburgh wall-clock time whatever the reader's own zone is, and the
137	 * definition travels with the file so a reader that doesn't know the zone by
138	 * name can still resolve it. The rules are the UK's standing ones (BST from the
139	 * last Sunday in March to the last Sunday in October), not a 2026 special case.
140	 */
141	const TZID = "Europe/London";
142	const VTIMEZONE = [
143	  "BEGIN:VTIMEZONE",
144	  `TZID:${TZID}`,
145	  "BEGIN:DAYLIGHT",
146	  "TZOFFSETFROM:+0000",
147	  "TZOFFSETTO:+0100",
148	  "TZNAME:BST",
149	  "DTSTART:19700329T010000",
150	  "RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=-1SU",
151	  "END:DAYLIGHT",
152	  "BEGIN:STANDARD",
153	  "TZOFFSETFROM:+0100",
154	  "TZOFFSETTO:+0000",
155	  "TZNAME:GMT",
156	  "DTSTART:19701025T020000",
157	  "RRULE:FREQ=YEARLY;BYMONTH=10;BYDAY=-1SU",
158	  "END:STANDARD",
159	  "END:VTIMEZONE",
160	];
161	
162	/**
163	 * An ICS (iCalendar) feed of the scheduled performances as VEVENTs.
164	 *
165	 * Written to survive the trip through Google Calendar's importer, which is
166	 * where these files actually end up: zoned times (see VTIMEZONE above), a UID
167	 * that stays put so re-importing an edited plan updates the events instead of
168	 * duplicating them, GEO alongside the text address so the map pin is right, and
169	 * a reminder early enough to walk there.
170	 *
171	 * @param {import("./engine.js").Slot[]} slots buildSchedule(...).scheduled
172	 * @param {{now?: Date, prodId?: string, calendarName?: string,
173	 *          alarmMinutes?: number|null}} [options]
174	 *   `now` stamps DTSTAMP (pass the current time from the browser; defaults to a
175	 *   fixed festival date so the function stays pure/testable when omitted).
176	 *   `alarmMinutes` sets the reminder lead time; pass null for no VALARM.
177	 * @returns {string} ICS text (CRLF line endings)
178	 */
179	export function toIcs(slots, options = {}) {
180	  const stamp = icsStamp(options.now ?? new Date(Date.UTC(2026, 7, 1)));
181	  const prodId = options.prodId || "-//EdFringeNow//Fringe Planner//EN";
182	  const calendarName = options.calendarName || "My Fringe Plan";
183	  const alarmMinutes = options.alarmMinutes === undefined ? 30 : options.alarmMinutes;
184	
185	  const lines = [
186	    "BEGIN:VCALENDAR",
187	    "VERSION:2.0",
188	    `PRODID:${prodId}`,
189	    "CALSCALE:GREGORIAN",
190	    "METHOD:PUBLISH",
191	    foldLine(`X-WR-CALNAME:${icsText(calendarName)}`),
192	    `X-WR-TIMEZONE:${TZID}`,
193	    ...VTIMEZONE,
194	  ];
195	
196	  for (const slot of slots || []) {
197	    const uid = `${slot.slug}-${icsLocal(slot.start)}@edfringenow.com`;
198	    const location = [slot.venueName, slot.room].filter(Boolean).join(", ");
199	    const descParts = [];
200	    if (slot.genre) descParts.push(slot.genre);
201	    if (slot.freeNonTicketed) descParts.push("Free — non-ticketed");
202	    if (slot.url) descParts.push(slot.url);
203	    descParts.push("Planned with EdFringeNow");
204	    lines.push(
205	      "BEGIN:VEVENT",
206	      foldLine(`UID:${uid}`),
207	      `DTSTAMP:${stamp}`,
208	      `DTSTART;TZID=${TZID}:${icsLocal(slot.start)}`,
209	      `DTEND;TZID=${TZID}:${icsLocal(slot.end)}`,
210	      foldLine(`SUMMARY:${icsText(slot.title)}`),
211	      foldLine(`LOCATION:${icsText(location)}`),
212	      foldLine(`DESCRIPTION:${icsText(descParts.join("\n"))}`),
213	      "STATUS:CONFIRMED",
214	      "TRANSP:OPAQUE"
215	    );
216	    // The venue's own coordinates, so the calendar pins the room rather than
217	    // geocoding a venue name that half a dozen Fringe venues share.
218	    if (slot.venueLat != null && slot.venueLng != null) {
219	      lines.push(`GEO:${slot.venueLat};${slot.venueLng}`);
220	    }
221	    if (slot.url) lines.push(foldLine(`URL:${icsText(slot.url)}`));
222	    if (alarmMinutes != null && alarmMinutes > 0) {
223	      lines.push(
224	        "BEGIN:VALARM",
225	        "ACTION:DISPLAY",
226	        foldLine(`DESCRIPTION:${icsText(slot.title)}`),
227	        `TRIGGER:-PT${Math.round(alarmMinutes)}M`,
228	        "END:VALARM"
229	      );
230	    }
231	    lines.push("END:VEVENT");
232	  }
233	
234	  lines.push("END:VCALENDAR");
235	  return lines.join("\r\n");
236	}
