80	/**
81	 * Rebuild the full show catalogue from the compact wire records + venues.json
82	 * lookups. Lossless: the records returned match the master shows.json, with
83	 * image/smallImage resolved to absolute https urls (the intended client form).
84	 *
85	 * Ticket status and soldOut do NOT come from the catalogue — they are the two
86	 * fields that move through the day, so they ship in their own sidecar
87	 * (availability.min.json) and are joined back on here. Without it every
88	 * performance is simply status-unknown, which is a state the engine and the
89	 * grid already draw: the planner stays usable if that fetch fails.
90	 *
91	 * @param {object[]} wire   parsed shows.min.json
92	 * @param {object}   lookups parsed venues.json ({venues, rooms, genres,
93	 *                           subgenres, ticketStatuses, ageRestrictions})
94	 * @param {number}   year    festival year the MMDD dates belong to
95	 * @param {object|null} availability parsed availability.min.json, or null
96	 * @returns {object[]} full show records
97	 */
98	export function rehydrateShows(wire, lookups, year = 2026, availability = null) {
99	  const { venues = {}, rooms = [], genres = [], subgenres = [],
100	          ageRestrictions = [] } = lookups || {};
101	  const at = (list, i) => (i >= 0 ? list[i] : null);
102	  return (wire || []).map((r) => {
103	    const room = at(rooms, r.rm);
104	    // venueName was dropped when it rebuilds from the venue code + room; the wire
105	    // form only carries `vn` for shows whose name can't be reconstructed.
106	    let venueName;
107	    if ("vn" in r) {
108	      venueName = r.vn;
109	    } else {
110	      const name = venues[r.v] ? venues[r.v].name : null;
111	      venueName = room ? `${room} at ${name}` : name;
112	    }
113	    const image = imageUrl(r.im);
114	    const perfKeys = performanceKeys(r.p);
115	    return {
116	      id: r.i,
117	      title: r.t,
118	      slug: r.sl,
119	      genre: at(genres, r.g),
120	      subgenres: (r.sg || []).map((i) => subgenres[i]),
121	      company: r.c ?? null,
122	      duration: r.d ?? null,
123	      ageRestriction: at(ageRestrictions, r.ar),
124	      free: r.f === 1,
125	      image,
126	      // smallImage is dropped when identical to image; the client mirrors it.
127	      smallImage: "si" in r ? imageUrl(r.si) : image,
128	      blurb: r.b ?? "",
129	      venue: r.v ?? null,
130	      venueName,
131	      room,
132	      performances: (r.p || []).map((p, i) => {
133	        const { status, soldOut } = performanceAvailability(availability, r.i, perfKeys[i]);
134	        return { date: mmddToDate(p.d, year), start: p.s, soldOut, status };
135	      }),
136	      // Real ticket prices in pounds, or null when the price cache doesn't
137	      // know this show. null is NOT £0 — only `free` means free. `px` is
138	      // dropped when the show has a single band, so max mirrors min.
139	      priceMin: r.pm ?? null,
140	      priceMax: r.px ?? r.pm ?? null,
141	    };
142	  });
143	}
