1	/* The Fringe day — where one festival day ends and the next begins.
2	 *
3	 * A calendar day is the wrong unit for a festival whose latest shows start at
4	 * midnight and after. At 23:50 the only question worth answering is "what can I
5	 * still get into tonight", and the honest answer includes the 00:30 show. A
6	 * midnight cut empties the page at exactly the moment someone is looking for a
7	 * later show, and hands them tomorrow's breakfast listings instead.
8	 *
9	 * So everything here works in FRINGE days: the day named "2026-08-14" runs from
10	 * 06:00 on the 14th to 06:00 on the 15th. 06:00 is the seam because it is the
11	 * quiet hour — the catalogue has nothing at all between 00:30 and 06:00 — so
12	 * the join falls where nobody is looking, and a show never lands on a day its
13	 * audience wouldn't call it.
14	 *
15	 * A time inside a fringe day is counted in minutes from that day's OWN midnight,
16	 * so the range is 360 (06:00) through 1799 (05:59 the next morning) and anything
17	 * past midnight is >= 1440. The "HH:MM" strings the page passes around carry the
18	 * same extension: 00:30 the next morning is "24:30", which keeps every string
19	 * comparison, sort and lookup key in the app correctly ordered. Only the display
20	 * layer wraps it back to "00:30" (clockHHMM / hourLabel).
21	 *
22	 * ONE boundary, defined once. The scraper buckets performances into day files by
23	 * it (scraper/normalize.py), the Now page picks its day file and its "now" by it
24	 * (js/app.js), the time wheel stops at it (js/constraint-time.js) and the
25	 * planner folds its late shows by it (plan/lib/engine.js). A second cut-off
26	 * anywhere would show up as shows that exist on one screen and not the other,
27	 * so new code reads the boundary from here rather than restating it — and a
28	 * test (shared/__tests__/fringe-day.test.mjs) holds the Python copy to the same
29	 * number.
30	 */
31	
32	/** Minutes in a calendar day. */
33	export const DAY_MINUTES = 1440;
34	
35	/** The seam: the clock time at which one fringe day becomes the next (06:00). */
36	export const FRINGE_DAY_START_MINUTES = 6 * 60;
37	
38	/** One past the last minute of a fringe day, in that day's own minutes: 06:00
39	 * the following morning (30:00 = 1800). Half-open, so a 06:00 show belongs to
40	 * the morning it happens in, not the night before — "7am Oboe Rave" is a
41	 * breakfast show, not a late one. */
42	export const FRINGE_DAY_END_MINUTES = FRINGE_DAY_START_MINUTES + DAY_MINUTES;
43	
44	/** "HH:MM" -> minutes. Accepts the extended hours (24–29) this module uses. */
45	export function timeToMinutes(hhmm) {
46	  const [h, m] = String(hhmm).split(":").map(Number);
47	  return h * 60 + m;
48	}
49	
50	/** Minutes -> extended "HH:MM": 1470 -> "24:30". The form the app stores. */
51	export function minutesToTime(minutes) {
52	  const r = Math.round(minutes);
53	  return `${String(Math.floor(r / 60)).padStart(2, "0")}:${String(r % 60).padStart(2, "0")}`;
54	}
55	
56	/** Minutes -> the "HH:MM" a person reads: 1470 -> "00:30". Display only. */
57	export function clockHHMM(minutes) {
58	  const r = ((Math.round(minutes) % DAY_MINUTES) + DAY_MINUTES) % DAY_MINUTES;
59	  return `${String(Math.floor(r / 60)).padStart(2, "0")}:${String(r % 60).padStart(2, "0")}`;
60	}
61	
62	/** An extended "HH:MM" as it should be shown: "24:30" -> "00:30". */
63	export function clockLabel(hhmm) {
64	  return hhmm ? clockHHMM(timeToMinutes(hhmm)) : hhmm;
65	}
66	
67	/** An extended hour ("24".."29") as it should be shown: "25" -> "01". */
68	export function hourLabel(hh) {
69	  return String(Number(hh) % 24).padStart(2, "0");
70	}
71	
72	/** True once a fringe-day time has crossed into the next calendar day. */
73	export function isAfterMidnight(minutes) {
74	  return minutes >= DAY_MINUTES;
75	}
76	
77	/** A "YYYY-MM-DD" shifted by whole days. UTC arithmetic so it can't be moved by
78	 * the host's zone or by a DST hop. */
79	export function shiftDate(dateISO, days) {
80	  const [y, m, d] = String(dateISO).split("-").map(Number);
81	  const dt = new Date(Date.UTC(y, m - 1, d + days));
82	  const p2 = (n) => String(n).padStart(2, "0");
83	  return `${dt.getUTCFullYear()}-${p2(dt.getUTCMonth() + 1)}-${p2(dt.getUTCDate())}`;
84	}
85	
86	/**
87	 * Which fringe day a real calendar moment belongs to.
88	 *
89	 * Before 06:00 you are still in the night before: the date moves back one and
90	 * the minutes move forward past 24:00, so 01:15 on the 15th is the 14th at 1515.
91	 *
92	 * Takes a date and a minute rather than a Date on purpose: which day a moment
93	 * falls in depends on the zone you read it in, and the answer this site wants is
94	 * always Edinburgh's. Callers pass what festivalNow (js/clock.js) read for them,
95	 * so there is no second, device-zone way to ask the same question.
96	 *
97	 * @param {string} dateISO real calendar date, "YYYY-MM-DD"
98	 * @param {number} minutesOfDay real minutes since that date's midnight (0–1439)
99	 * @returns {{date: string, minutes: number}} fringe date + minutes within it
100	 */
101	export function fringeMoment(dateISO, minutesOfDay) {
102	  if (minutesOfDay < FRINGE_DAY_START_MINUTES) {
103	    return { date: shiftDate(dateISO, -1), minutes: minutesOfDay + DAY_MINUTES };
104	  }
105	  return { date: dateISO, minutes: minutesOfDay };
106	}
107	
108	/**
109	 * The real calendar moment behind a fringe-day time — the inverse of
110	 * fringeMoment. Anything a third party has to understand (a booking link's
111	 * date, a calendar entry) needs the real date, not the fringe one.
112	 *
113	 * @param {string} fringeDate "YYYY-MM-DD" of the fringe day
114	 * @param {number|string} time minutes within it, or an extended "HH:MM"
115	 * @returns {{date: string, time: string}} real date + real "HH:MM"
116	 */
117	export function realMoment(fringeDate, time) {
118	  const minutes = typeof time === "number" ? time : timeToMinutes(time);
119	  const days = Math.floor(minutes / DAY_MINUTES);
120	  return { date: shiftDate(fringeDate, days), time: clockHHMM(minutes) };
121	}
