1	/* Human-friendly durations, shared by both front-ends.
2	 *
3	 * A spare-time figure is a number the user has to *feel*, not audit. "You have
4	 * 287 min to spare" is arithmetically perfect and useless — nobody converts
5	 * that to "most of an afternoon" while standing on a street corner. So the
6	 * phrasing changes with the size of the gap, and precision is deliberately
7	 * traded away as the number grows:
8	 *
9	 *   under an hour   exact minutes          "45 minutes"
10	 *   one to two hrs  hours and minutes      "1 hour and 20 minutes"
11	 *   over two hours  nearest half hour      "about 2½ hours"
12	 *
13	 * The last band is the point of the whole module: past two hours the minutes
14	 * are noise, and rounding to the nearest half hour with an explicit "about"
15	 * is more honest about what the estimate is worth than a to-the-minute figure.
16	 *
17	 * Both pages import this as `../shared/duration.js` (which resolves to
18	 * `/shared/duration.js` from either).
19	 */
20	
21	/* The band boundaries, in minutes. Exactly 60 and exactly 120 read as whole
22	 * hours ("1 hour" / "2 hours") rather than falling to a minutes-only or an
23	 * "about" phrasing — a round number should look round. */
24	const AN_HOUR = 60;
25	const TWO_HOURS = 120;
26	
27	/** Pluralize a whole-number count: `unitize(1, "hour")` -> "1 hour". */
28	function unitize(n, unit) {
29	  return `${n} ${unit}${n === 1 ? "" : "s"}`;
30	}
31	
32	/**
33	 * A duration in minutes, phrased the way a person would say it (see the bands
34	 * at the top of this file).
35	 *
36	 * Negative and non-finite inputs return an empty string: this formats a
37	 * quantity of spare time, and "minus 20 minutes to spare" is not a sentence.
38	 * Callers that need to express a deficit (arriving late) say so themselves and
39	 * pass the absolute value.
40	 *
41	 * @param {number} mins duration in minutes
42	 * @returns {string} e.g. "45 minutes", "1 hour and 20 minutes", "about 2½ hours"
43	 */
44	export function friendlyDuration(mins) {
45	  if (!Number.isFinite(mins) || mins < 0) return "";
46	  const m = Math.round(mins);
47	
48	  if (m < AN_HOUR) return unitize(m, "minute");
49	
50	  if (m <= TWO_HOURS) {
51	    const hours = Math.floor(m / AN_HOUR);
52	    const rest = m - hours * AN_HOUR;
53	    // 120 floors to 2 hours with nothing left over, so exactly two hours reads
54	    // as "2 hours" and never reaches the "about" band below.
55	    if (rest === 0) return unitize(hours, "hour");
56	    return `${unitize(hours, "hour")} and ${unitize(rest, "minute")}`;
57	  }
58	
59	  // Past two hours: round to the nearest half hour and admit the imprecision.
60	  const halves = Math.round(m / 30);
61	  const hours = Math.floor(halves / 2);
62	  const half = halves % 2 === 1;
63	  const label = half ? `${hours}½ hours` : unitize(hours, "hour");
64	  return `about ${label}`;
65	}
