242	// --- Data loading + rehydration ---------------------------------------
243	//
244	// The planner downloads three files up front: the compact catalogue
245	// (shows.min.json, packed by scraper/normalize.py), the shared lookups
246	// (venues.json) and the availability sidecar (availability.min.json).
247	// rehydrateShows() (./lib/hydrate.js) joins them back into the full records the
248	// engine expects — every enum is an index into a venues.json list, venueName is
249	// rebuilt from the venue code + room, dates are MMDD ints, the bare image GUID
250	// gets its host prefix re-attached, and each performance picks up its ticket
251	// status from the sidecar — so the rest of the app sees a ready-to-use
252	// catalogue identical in shape to the old shows.json.
253	//
254	// The three are split the way they are so each can be cached for as long as its
255	// contents actually last: see the TTL constants above. Availability is the only
256	// one of them that moves through the day, and it is the smallest.
257	//
258	// A fourth file — the descriptions sidecar — follows *after* those have landed,
259	// and nothing waits for it: see loadDescriptions.
260	
261	let dataPromise = null;
262	
263	function loadData() {
264	  dataPromise = (async () => {
265	    // All three are wanted to rehydrate, so they are fetched together. Only
266	    // availability is allowed to fail: without it every performance is
267	    // status-unknown, which the grid already draws, and a planner with no
268	    // availability beats no planner at all.
269	    const [wire, lookups, availability] = await Promise.all([
270	      cachedFetchJson(DATA_URL, CATALOGUE_TTL_MS, noteCache),
271	      cachedFetchJson(VENUES_URL, LOOKUPS_TTL_MS, noteCache),
272	      cachedFetchJson(AVAILABILITY_URL, AVAILABILITY_TTL_MS, noteCache).catch((err) => {
273	        console.info("Fringe Planner: ticket availability unavailable", err);
274	        return null;
275	      }),
276	    ]);
277	    state.venueCoords = lookups.venues || null; // venue map drives travel legs/gaps
278	    state.lookups = lookups;
279	    state.catalogue = rehydrateShows(wire, lookups, YEAR, availability);
280	    state.index = buildIndex(state.catalogue);
281	    state.facets = catalogueFacets(state.catalogue);
282	    initSearchUI();
283	    restoreStoredFavourites();
284	    // Deliberately not awaited: the page is fully usable without descriptions,
285	    // and starting them here rather than alongside the catalogue keeps them off
286	    // the critical path entirely.
287	    loadDescriptions();
288	    return state.index;
289	  })();
290	  dataPromise.catch(() => {});
291	  return dataPromise;
292	}
