294	/* Where the shared data cache (shared/data-cache.js) reports a cache write it
295	 * couldn't make or a stale copy it fell back on. Never surfaced in the UI: in
296	 * both cases the caller still got its data. */
297	function noteCache(err, url) {
298	  console.info("Fringe Planner: data cache —", url, err);
299	}
