301	/**
302	 * The descriptions sidecar: slug → the show's full text, fetched once per page
303	 * and cached for a week. Everything it feeds already works without it — the
304	 * hover card falls back to the catalogue's one-line blurb, and so does search —
305	 * so a failure here is logged and dropped, never surfaced. When it does land,
306	 * an open search re-runs so the results deepen under the query already typed.
307	 */
308	function loadDescriptions() {
309	  if (state.descriptionsPromise) return state.descriptionsPromise;
310	  state.descriptionsPromise = cachedFetchJson(DESCRIPTIONS_URL, DESCRIPTIONS_TTL_MS, noteCache)
311	    .then((payload) => {
312	      state.descriptions = new Map(Object.entries((payload && payload.d) || {}));
313	      if (!$("ssPop").hidden) runSearch();
314	      return state.descriptions;
315	    })
316	    .catch((err) => {
317	      console.info("Fringe Planner: descriptions unavailable — using blurbs", err);
318	      return null;
319	    });
320	  return state.descriptionsPromise;
321	}
