324	 *  catalogue's own truncated blurb until then. */
325	function descriptionFor(slug) {
326	  const full = state.descriptions.get(slug);
327	  if (full) return full;
328	  const show = showBySlug(slug);
329	  return (show && show.blurb) || "";
