336	  $("loadingState").hidden = false;
337	  try {
338	    return await dataPromise;
339	  } catch (err) {
340	    dataPromise = null;
341	    throw err;
342	  } finally {
343	    $("loadingState").hidden = true;
344	  }
345	}
