2636	function windowScore(d0, d1) {
2637	  const a = dateStr(d0);
2638	  const b = dateStr(d1);
2639	  let shows = 0;
2640	  let dates = 0;
2641	  for (const show of state.matched) {
2642	    let n = 0;
2643	    for (const p of show.performances || []) {
2644	      if (p.date >= a && p.date <= b && isAvailable(p)) n++;
