2652	/** Count the weekend days (Sat/Sun) within an inclusive day-of-month range. */
2653	function weekendDays(d0, d1) {
2654	  let n = 0;
2655	  for (let d = d0; d <= d1; d++) if (isWeekend(d)) n++;
2656	  return n;
2657	}
2658	
2659	/**
2660	 * Best placement for a fixed-length window. Without "weekends", it maximises
2661	 * shows caught (then catchable dates). With "weekends" on, it first maximises
2662	 * the weekend days the window covers — so the trip lands on the busiest Fringe
2663	 * days — then breaks ties by shows, then dates.
2664	 */
2665	function optimizeDates(days, weekends) {
2666	  const len = clamp(days, 1, DAYS_IN_MONTH);
2667	  let best = null;
2668	  for (let d0 = 1; d0 + len - 1 <= DAYS_IN_MONTH; d0++) {
2669	    const d1 = d0 + len - 1;
2670	    const score = windowScore(d0, d1);
2671	    const cand = { d0, d1, wknd: weekends ? weekendDays(d0, d1) : 0, ...score };
2672	    if (!best) { best = cand; continue; }
2673	    const better = weekends
2674	      ? cand.wknd > best.wknd ||
2675	        (cand.wknd === best.wknd && (cand.shows > best.shows || (cand.shows === best.shows && cand.dates > best.dates)))
2676	      : cand.shows > best.shows || (cand.shows === best.shows && cand.dates > best.dates);
2677	    if (better) best = cand;
2678	  }
2679	  return best;
2680	}
