3496	/** A decor layer element for a region: `<span>` the fill routine paints into.
3497	 *  `set` names an emoji palette (DECOR_SETS); `seed` keeps two same-set regions
3498	 *  (lunch vs dinner, arrival vs departure) scattering differently. */
3499	function decorSpan(set, seed) {
3500	  return `<span class="sch-decor" data-decor="${set}" data-seed="${seed}" aria-hidden="true"></span>`;
3501	}
3502	
3503	// The scatter is laid on a fixed pixel grid (one jittered emoji per cell), not a
3504	// percentage cloud, so it never stretches: a wider region just gains more cells
3505	// at the same density. Positions/emoji are a deterministic hash of the cell
3506	// index + the region's seed, so it stays put across re-plans and a resize only
3507	// *appends* emoji — the ones already on screen don't jump. Cached by seed+set+
3508	// rounded size so re-plans at the same size reuse the string.
3509	const decorCache = new Map();
3510	
3511	// ~96px per inch; 5 emoji per square inch → one cell every 96/√5 ≈ 43px.
3512	const DECOR_CELL_PX = 43;
3513	
3514	/** A stable 0..1 pseudo-random from three integers (cell x, cell y, salt). */
3515	function decorHash(x, y, salt) {
3516	  let h = (Math.imul(x, 73856093) ^ Math.imul(y, 19349663) ^ Math.imul(salt, 83492791)) >>> 0;
3517	  h ^= h >>> 13;
3518	  h = Math.imul(h, 0x5bd1e995) >>> 0;
3519	  h ^= h >>> 15;
3520	  return (h >>> 0) / 4294967296;
3521	}
3522	
3523	/** A small integer seed from a string, so different regions scatter differently. */
3524	function decorSalt(str) {
3525	  let h = 2166136261;
3526	  for (let i = 0; i < str.length; i++) h = Math.imul(h ^ str.charCodeAt(i), 16777619);
3527	  return h >>> 0;
3528	}
