3553	/** Fill every decor layer on the board once sizes are known (meal bands, the
3554	 *  day-start/day-end zones, the trip blocks). Cached by seed+set+rounded size so
3555	 *  scrubbing the plan doesn't reshuffle the emoji. */
3556	function populateDecors(host) {
3557	  for (const decor of host.querySelectorAll(".sch-decor")) {
3558	    const region = decor.parentElement;
3559	    const w = region.clientWidth || 600;
3560	    const h = region.clientHeight || 34;
3561	    const setName = decor.dataset.decor || "food";
3562	    const seed = decor.dataset.seed || setName;
3563	    const key = `${setName}:${seed}:${Math.round(w / 16)}:${Math.round(h / 16)}`;
3564	    // Skip untouched layers: the same region at the same tile-count keeps its
3565	    // spans (and their in-flight CSS drift). This makes re-tiling on every drag
3566	    // frame a no-op until a region actually crosses a 16px tile boundary.
3567	    if (decor.dataset.decorKey === key) continue;
3568	    decor.dataset.decorKey = key;
3569	    let html = decorCache.get(key);
3570	    if (html == null) {
3571	      html = buildDecorHTML(w, h, setName, seed);
3572	      decorCache.set(key, html);
3573	    }
3574	    decor.innerHTML = html;
3575	  }
