3798	  const axisH = ((axisBottomMin - axisTopMin) / 60) * hourPx;
3799	  const y = (min) => ((clamp(min, axisTopMin, axisBottomMin) - axisTopMin) / 60) * hourPx;
3800	  const dayEnd = effectiveDayEnd();
3801	
3802	  const zones = overlay.querySelectorAll(".sch-zone");
3803	  if (zones[0]) zones[0].style.height = `${y(state.dayStartMin)}px`;
3804	  if (zones[1]) {
3805	    zones[1].style.top = `${y(dayEnd)}px`;
3806	    zones[1].style.height = `${axisH - y(dayEnd)}px`;
3807	    toggleNagFit(zones[1], axisH - y(dayEnd));
3808	  }
3809	  const startLine = overlay.querySelector(".sch-dayline--start");
3810	  if (startLine) {
3811	    startLine.style.top = `${y(state.dayStartMin)}px`;
3812	    startLine.querySelector(".dl-flag .ov-text").textContent = `Day starts ${minToHHMM(state.dayStartMin)}`;
3813	  }
3814	  const endLine = overlay.querySelector(".sch-dayline--end");
3815	  if (endLine) {
3816	    endLine.style.top = `${y(dayEnd)}px`;
3817	    endLine.querySelector(".dl-flag .ov-text").textContent = `Day ends ${minToDayClock(dayEnd)}`;
3818	  }
3819	  for (const meal of state.mealBreaks) {
3820	    if (!meal.enabled) continue;
3821	    const band = overlay.querySelector(`.sch-meal[data-meal="${meal.id}"]`);
3822	    if (!band) continue;
3823	    band.style.top = `${y(meal.startMin)}px`;
