4058	/** Parse an "HH:MM" day-clock string to minutes-of-day, allowing the extended
4059	 *  Fringe range (hours up to 27 for a 03:00 finish). Null if malformed. */
4060	function parseDayClock(str) {
4061	  const m = /^\s*(\d{1,2}):(\d{2})\s*$/.exec(str || "");
4062	  if (!m) return null;
4063	  const h = Number(m[1]);
4064	  const mi = Number(m[2]);
4065	  if (h > 27 || mi > 59) return null;
4066	  return h * 60 + mi;
4067	}
