4139	function downloadText(filename, text, mime) {
4140	  const blob = new Blob([text], { type: mime });
4141	  const url = URL.createObjectURL(blob);
4142	  const a = document.createElement("a");
4143	  a.href = url;
4144	  a.download = filename;
