1326	/* Ink-stamp overlay on cards that are sold out / no longer reachable — a bold
1327	 * boxed word, roughened at the edges (SVG #stamp-ink filter) and eaten away in
1328	 * patches (a turbulence mask) so it reads like a real rubber stamp. The card
1329	 * stays clickable — the stamp ignores pointer events. */
1330	.show-stamp {
1331	  position: absolute; top: 50%; left: 50%;
1332	  transform: translate(-50%, -50%) rotate(-7deg);
1333	  z-index: 3; pointer-events: none;
1334	  /* Heavy slab display face — the chunky letterform is what reads as a stamp
1335	   * (loaded via Google Fonts in index.html). Alfa Slab One is already bold. */
1336	  font-family: "Alfa Slab One", Rockwell, "Roboto Slab", var(--serif), serif;
1337	  font-weight: 400; font-size: 1.1rem; line-height: 1;
1338	  letter-spacing: 0.01em; text-transform: uppercase; white-space: nowrap;
1339	  padding: 6px 15px 3px;
1340	  border: 3px solid currentColor; border-radius: 4px;
1341	  background: transparent;
1342	  opacity: 0.85;
1343	  /* Straight-ish edges (small displacement) — the worn look comes from the mask,
1344	   * not from warping the box. */
1345	  filter: url(#stamp-ink);
