/* ===================== Header ===================== */
.site-header {
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(6px);
  z-index: 1000;
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: 24px;
}
/* Headers that carry the primary nav become three columns instead, so "Now /
   Plan" sits on the page's centre line rather than in the middle of whatever
   space the logo and the header icons happen to leave over (those two are
   never the same width, so auto margins put the nav off-centre). Legal pages
   have no nav and keep the plain two-item flex row above. */
.header-inner:has(.main-nav) {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
}
.header-inner:has(.main-nav) > :first-child { justify-self: start; }
.header-inner:has(.main-nav) > :last-child { justify-self: end; }
.logo {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.4rem;
  letter-spacing: -0.01em;
  color: var(--ink);
  text-decoration: none;
  white-space: nowrap;
}
.logo-now { color: var(--red); }
.main-nav {
  display: flex;
  gap: 28px;
}
.nav-link {
  text-decoration: none;
  color: var(--ink);
  font-size: 0.98rem;
  padding-bottom: 2px;
  border-bottom: 2px solid transparent;
}
.nav-link:hover { color: var(--red); }
.nav-link.is-active {
  color: var(--red);
  border-bottom-color: var(--red);
}
.header-icons { display: flex; gap: 8px; }

.icon-btn {
  display: inline-grid;
  place-items: center;
/* The focused show and the committed destination are highlighted in the page's
   violet — the same 1px ring as every other pin, just recoloured, plus a faint
   violet tint. No size change, so the map's density is unaffected. */
.gpin--selected, .gpin--leg { background: rgba(108, 76, 241, 0.18); border: 1px solid var(--gold); }
