   plugin's default coloured circles, whose skin CSS we don't load). */
.genre-cluster { background: none; }
.gcluster { display: flex; align-items: center; justify-content: center; border-radius: 50%; background: var(--gold); color: #fff; font-weight: 700; font-size: 0.78rem; border: 2px solid #fff; box-shadow: 0 1px 4px rgba(16, 24, 40, 0.35); }
/* Fade the count bubbles while a show is focused, to match the dimmed pins. */
.gcluster--dim { opacity: 0.3; }
/* Leaflet attribution links — styled in site purple */
.leaflet-control-attribution { font-size: 0.65rem; }
.leaflet-control-attribution a { color: var(--blue); text-decoration: underline; }
.leaflet-control-attribution a:hover { color: var(--blue-dark); }

