// Determinism spike: render the Now page twice in fresh contexts and compare.
"use strict";
const fs = require("node:fs");
const { newPage, closeBrowser, ORIGIN } = require("/home/user/EdFringeNow/product/requirements/shared/harness/browser.js");
const { decode } = require("/home/user/EdFringeNow/product/requirements/shared/png.js");

const OUT = process.argv[2] || "/tmp/claude-0/-home-user-EdFringeNow/4718d745-fa40-5876-be9d-ab6c18d4aaf8/scratchpad";

async function render(tag) {
  const { page, context } = await newPage({
    localStorage: { "edfringenow.now.intro.v1": JSON.stringify({ dismissed: true }) },
  });
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
  await page.goto(`${ORIGIN}/`, { waitUntil: "networkidle" });
  await page.waitForSelector("#showsGrid .show-item, #showsGrid .show-meta", { timeout: 15000 });
  await page.waitForTimeout(400);
  const png = await page.screenshot({ fullPage: true });
  fs.writeFileSync(`${OUT}/spike-${tag}.png`, png);
  await context.close();
  const heading = await "";
  return { png, errors };
}

(async () => {
  const a = await render("a");
  const b = await render("b");
  await closeBrowser();
  console.log("errors A:", a.errors.length ? a.errors : "none");
  console.log("byte-identical:", a.png.equals(b.png));
  if (!a.png.equals(b.png)) {
    const da = decode(a.png), db = decode(b.png);
    console.log("dims", da.width, da.height, "vs", db.width, db.height);
    if (da.width === db.width && da.height === db.height) {
      let n = 0;
      for (let i = 0; i < da.rgba.length; i++) if (da.rgba[i] !== db.rgba[i]) n++;
      console.log("differing bytes:", n, "of", da.rgba.length);
    }
  }
})().catch((e) => { console.error(e); process.exit(1); });

