1	// One-time freezer for the requirements fixture dataset. Run from the repo
2	// root: `node product/requirements/shared/fixtures/build-fixtures.js`.
3	//
4	// It derives the fixtures from the repo's real committed data (real bytes,
5	// real schema — never hand-invented records), selecting a small, curated cast
6	// of shows that spans every UI state the spec asserts: available / sold-out /
7	// free / price-unknown / tight-timing on the Now page; every availability
8	// colour, a sold-out lane, a no-dates lane and a lunch-conflict lane on the
9	// planner. The outputs are committed and FROZEN — the live data refreshes
10	// nightly, the fixtures do not. Re-running this script against newer data
11	// changes the cast and therefore every golden; that is a deliberate,
12	// owner-approved re-baselining, never routine.
13	//
14	// Documented deviations from the source bytes (each marked ADJUST below):
15	//   1. planner: every performance of one favourite is forced sold-out, so the
16	//      "Sold out" lane verdict is renderable.
17	//   2. planner: one favourite is trimmed to a single available performance, so
18	//      pinning a clashing show renders the "Can't fit" verdict.
19	"use strict";
20	
21	const fs = require("node:fs");
22	const path = require("node:path");
23	const { encode } = require("../png");
24	
25	const ROOT = path.join(__dirname, "..", "..", "..", "..");
26	const OUT = path.join(__dirname, "data");
27	const read = (p) => JSON.parse(fs.readFileSync(path.join(ROOT, p), "utf8"));
28	const write = (rel, value) => {
29	  const p = path.join(OUT, rel);
30	  fs.mkdirSync(path.dirname(p), { recursive: true });
31	  fs.writeFileSync(p, JSON.stringify(value));
32	  console.log(`wrote ${rel}`);
33	};
34	
35	// ---------------------------------------------------------------- the cast --
36	// Now page (day file 2026-08-15, reference now 19:30): chosen for the states
37	// the §1–§8 leaves assert. Walk minutes are from the fixed fake location.
38	const NOW_SLUGS = [
39	  "ray-bradshaw-five-years-in-a-row", // 19:45, walk 6 — SOLD OUT stamp
40	  "david-alnwick-the-haunted-magician", // 19:40, walk 4 — Free
41	  "the-inverted-realm", // 20:55, walk 10 — no pm: Price TBC
42	  "likewise", // 19:35, walk 9 — arrival 19:39: TOO LATE (tight)
43	  "monks", // 19:35, walk 10 — hidden at default 10-min budget? kept: exactly 10
44	  "shinjuku", // 19:35, walk 10
45	  "front-for-something", // 20:00, walk 8 — free
46	  "the-mysterious-seelie-wight-women", // 20:30, walk 4 — sold out (2nd)
47	  "abandoman-afterglow", // 20:55, walk 10 — sold out (3rd)
48	];
49	// Constraint-picker targets: the default wheel time is 21:30 (19:30 + 2 h).
50	// Kept regardless of distance — the picker deliberately ignores every filter.
51	const CONSTRAINT_SLUGS = [];
52	
53	// Planner favourites: the CSV upload + verdict variety across the 7–24 window.
54	const PLAN_FAVOURITE_SLUGS = [];
55	
56	// ---------------------------------------------------------------- load real --
57	const venues = read("data/venues.json");
58	const day15 = Object.values(read("data/days/2026-08-15.json"));
59	const day14 = Object.values(read("data/days/2026-08-14.json"));
60	const catalogue = read("data/normalized/shows.min.json");
61	const availability = read("data/normalized/availability.min.json");
62	
63	const TS = venues.ticketStatuses;
64	const tsIndex = (name) => {
65	  const i = TS.indexOf(name);
66	  if (i < 0) throw new Error(`status ${name} not in venues.json`);
67	  return i;
68	};
69	
70	// Constraint picker: two real 21:30 starters (any venue).
71	for (const e of day15) {
72	  if (e.start === "21:30" && CONSTRAINT_SLUGS.length < 2) CONSTRAINT_SLUGS.push(e.slug);
73	}
74	if (CONSTRAINT_SLUGS.length < 2) throw new Error("no 21:30 starters on 2026-08-15");
75	
76	// A show far beyond the default 10-minute walk budget (about 25–40 min out),
77	// for the "beyond the travel budget never appears" proof.
78	const U = { lat: 55.9523946827963, lng: -3.188258484671504 };
79	const distKm = (a, b) => {
80	  const r = (x) => (x * Math.PI) / 180;
81	  const dl = r(b.lat - a.lat);
82	  const dg = r(b.lng - a.lng);
83	  const s = Math.sin(dl / 2) ** 2 + Math.cos(r(a.lat)) * Math.cos(r(b.lat)) * Math.sin(dg / 2) ** 2;
84	  return 2 * 6371 * Math.asin(Math.sqrt(s));
85	};
86	const walkMin = (e) => {
87	  const ven = venues.venues[e.venue];
88	  if (!ven || ven.lat == null) return null;
89	  return (distKm(U, ven) / (10 / 3)) * 60;
90	};
91	const far = day15.find((e) => {
92	  const w = walkMin(e);
93	  return w !== null && w > 25 && w < 40 && e.start === "20:00" && !e.free;
94	});
95	if (!far) throw new Error("no far show found");
