+  const browser = await launchBrowser();
+  const geolocation = opts.geolocation === undefined ? GEOLOCATION : opts.geolocation;
+  const context = await browser.newContext({
+    viewport: VIEWPORTS[opts.viewport || "mobile"],
+    deviceScaleFactor: 1,
+    locale: LOCALE,
+    timezoneId: TIMEZONE,
