    assert.deepEqual(parseFavourites(csv), ["show-a", "show-b"]);

    // Fallback: a plain list of URLs or bare slugs, comments and blanks ignored.
    const plain = "# my list\nhttps://www.edfringe.com/tickets/whats-on/show-c\n\nshow-d\n";
    assert.deepEqual(parseFavourites(plain), ["show-c", "show-d"]);
  },
};

