"use strict";
const path = require("node:path");
const R = "/home/user/EdFringeNow/product/requirements/shared";
const { newPage, ORIGIN } = require(path.join(R, "harness/browser"));
const { nowReady, nowStorage } = require(path.join(R, "case-helpers"));

(async () => {
  const { page, context } = await newPage({ localStorage: nowStorage() });
  await page.goto(`${ORIGIN}/`, { waitUntil: "load" });
  await nowReady(page);
  const cdp = await context.newCDPSession(page);
  await cdp.send("DOM.enable");
  await cdp.send("CSS.enable");
  const { root } = await cdp.send("DOM.getDocument", { depth: -1, pierce: true });
  // walk all nodes, collect platform fonts for element nodes with text
  const seen = new Map();
  async function walk(node) {
    if (node.nodeType === 1) {
      try {
        const { fonts } = await cdp.send("CSS.getPlatformFontsForNode", { nodeId: node.nodeId });
        for (const f of fonts || []) {
          const key = f.familyName + (f.isCustomFont ? " [custom]" : " [SYSTEM]");
          seen.set(key, (seen.get(key) || 0) + f.glyphCount);
        }
      } catch {}
    }
    for (const c of node.children || []) await walk(c);
  }
  await walk(root);
  console.log([...seen.entries()].sort((a,b)=>b[1]-a[1]).map(([k,v])=>`${v}\t${k}`).join("\n"));
  await context.close();
  process.exit(0);
})();
