1	// The requirements harness's browser: pinned Playwright Chromium, a hermetic
2	// fake origin served from disk, and every nondeterministic input replaced —
3	// clock, location, randomness, network (fonts, Leaflet, map tiles, geocoding,
4	// live data). Every UI case (screen and behavior kinds alike) gets its page
5	// from here, so "deterministic" is decided once, not per case.
6	//
7	// The page is served from a FAKE origin (http://edfringenow.req/), fulfilled
8	// entirely from the repo working tree + committed fixtures via route
9	// interception — no HTTP server process, no port, nothing off-disk. Any request
10	// the routing table doesn't recognise is aborted, so a new external dependency
11	// in the product breaks the suite loudly instead of adding hidden network.
12	"use strict";
13	
14	const fs = require("node:fs");
15	const path = require("node:path");
16	const { execSync } = require("node:child_process");
17	const { pathToFileURL } = require("node:url");
18	
19	const REPO_ROOT = path.join(__dirname, "..", "..", "..", "..");
20	const VENDOR_DIR = path.join(__dirname, "vendor");
21	const FIXTURES_DIR = path.join(__dirname, "..", "fixtures");
22	const { REFERENCE_NOW_UTC_MS, TIMEZONE, LOCALE, GEOLOCATION } = require("../reference-now");
23	
24	// Rendering is only comparable against the committed goldens when the exact
25	// same Chromium rasterises it. This is the Playwright whose vendored browser
26	// the goldens were rendered with; the runner refuses to compare with any other.
27	const PINNED_PLAYWRIGHT = "1.56.1";
28	
29	// https, not http: geolocation only exists on secure origins. Routes are
30	// fulfilled before any real connection, so no certificate is involved.
31	const ORIGIN = "https://edfringenow.req";
32	
33	// The two committed viewports. A case says `viewport: "desktop"`; everything
34	// else about the screen (DPR 1, no touch) is fixed here.
35	const VIEWPORTS = {
36	  mobile: { width: 390, height: 844 },
37	  desktop: { width: 1280, height: 900 },
38	};
39	
40	const MIME = {
41	  ".html": "text/html; charset=utf-8",
42	  ".js": "text/javascript; charset=utf-8",
43	  ".mjs": "text/javascript; charset=utf-8",
44	  ".css": "text/css; charset=utf-8",
45	  ".json": "application/json; charset=utf-8",
46	  ".png": "image/png",
47	  ".svg": "image/svg+xml",
48	  ".webp": "image/webp",
49	  ".ico": "image/x-icon",
50	  ".woff2": "font/woff2",
51	  ".csv": "text/csv; charset=utf-8",
52	  ".txt": "text/plain; charset=utf-8",
53	};
54	
55	// Playwright resolves differently per environment: CI installs it into
56	// node_modules (a plain import), the Claude sandbox ships it globally beside a
57	// pre-provisioned browser. Try the local install first, then the global build
58	// by its ESM entry (the CJS index.js yields undefined named exports).
59	async function loadPlaywright() {
60	  try {
61	    return await import("playwright");
62	  } catch {
63	    /* no local install — fall through to the global build */
64	  }
65	  const guesses = ["/opt/node22/lib/node_modules/playwright/index.mjs"];
66	  try {
67	    guesses.push(path.join(execSync("npm root -g", { encoding: "utf8" }).trim(), "playwright", "index.mjs"));
68	  } catch {
69	    /* npm unavailable — the hardcoded guess still stands */
70	  }
71	  for (const g of guesses) {
72	    if (fs.existsSync(g)) return import(pathToFileURL(g).href);
73	  }
74	  throw new Error(
75	    "Playwright not found. Install the pinned version locally: npm i --no-save playwright@" +
76	      PINNED_PLAYWRIGHT +
77	      " && npx playwright install chromium"
78	  );
79	}
80	
81	function playwrightVersion() {
82	  const candidates = [
83	    path.join(REPO_ROOT, "node_modules", "playwright", "package.json"),
84	    "/opt/node22/lib/node_modules/playwright/package.json",
85	  ];
86	  for (const c of candidates) {
87	    if (fs.existsSync(c)) return JSON.parse(fs.readFileSync(c, "utf8")).version;
88	  }
89	  return null;
90	}
91	
92	// Deterministic Math.random for the page: mulberry32, fixed seed. Runs before
93	// any page script.
94	const SEEDED_RANDOM = `
95	  (() => {
96	    let s = 0xedf12026;
97	    Math.random = function () {
98	      s |= 0; s = (s + 0x6d2b79f5) | 0;
99	      let t = Math.imul(s ^ (s >>> 15), 1 | s);
100	      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
101	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
102	    };
103	  })();
104	`;
105	
106	// Freeze every visual in flight: CSS animations/transitions land on their end
107	// state, the text caret never blinks, smooth scrolling is instant. Injected at
108	// document start so nothing renders un-frozen.
109	const FREEZE_CSS = `
110	  *, *::before, *::after {
111	    animation-duration: 0s !important;
112	    animation-delay: 0s !important;
113	    transition-duration: 0s !important;
114	    transition-delay: 0s !important;
115	    caret-color: transparent !important;
116	    scroll-behavior: auto !important;
117	  }
118	`;
119	
120	function fulfillFile(route, filePath, status = 200) {
121	  const ext = path.extname(filePath).toLowerCase();
122	  return route.fulfill({
123	    status,
124	    contentType: MIME[ext] || "application/octet-stream",
125	    body: fs.readFileSync(filePath),
126	  });
127	}
128	
129	// The routing table: URL → bytes, worked out once for the whole suite.
130	//   - our fake origin: fixtures override, then vendor, then the repo tree;
131	//   - Google Fonts CSS + unpkg Leaflet/markercluster: the committed vendor copies;
132	//   - OSM tiles: one committed fixture tile, whatever the coordinates;
133	//   - the geocoder: the committed fixture response (cases exercise "found");
134	//   - anything else: aborted.
135	async function routeAll(context, { dataDir, failData }) {
136	  await context.route("**/*", (route) => {
137	    const url = new URL(route.request().url());
138	    const { hostname, pathname } = url;
139	
140	    // Simulated outage: a case may declare URL substrings that must fail, to
141	    // drive the product's error states (a dead geocoder, a failed catalogue).
142	    if (failData && failData.some((s) => url.href.includes(s))) {
143	      return route.abort("failed");
144	    }
145	
146	    // Vendored assets, on ANY host: the fonts CSS is served from the Google
147	    // Fonts URL, so its url(/__vendor/…) references resolve against that host.
148	    if (pathname.startsWith("/__vendor/")) {
149	      const v = path.join(VENDOR_DIR, pathname.slice("/__vendor/".length).replace("fonts/", "fonts" + path.sep));
150	      if (fs.existsSync(v)) return fulfillFile(route, v);
151	      return route.abort();
152	    }
153	
154	    if (`${url.protocol}//${hostname}` === ORIGIN) {
155	      const rel = decodeURIComponent(pathname.replace(/^\/+/, "")) || "index.html";
156	      const withIndex = rel.endsWith("/") || rel === "" ? `${rel}index.html` : rel;
157	      // The version the footer/debug pill shows must not drift with releases.
158	      // (Stored as .fixture so no stray package.json lands in the tree.)
159	      if (withIndex === "package.json") {
160	        return route.fulfill({
161	          contentType: MIME[".json"],
162	          body: fs.readFileSync(path.join(FIXTURES_DIR, "package.json.fixture")),
163	        });
164	      }
