+// Freeze every visual in flight: CSS animations/transitions land on their end
+// state, the text caret never blinks, smooth scrolling is instant. Injected at
+// document start so nothing renders un-frozen.
+const FREEZE_CSS = `
+  *, *::before, *::after {
