1	// The pixel comparator: a rendered actual against its committed golden, at
2	// ZERO tolerated difference. The harness pins every nondeterministic input, so
3	// any differing pixel is a real change to the product's surface — if rendering
4	// ever proves unstable, the fix is more determinism (fonts, clock, fakes),
5	// never a threshold.
6	"use strict";
7	
8	const fs = require("node:fs");
9	const { decode, encode, isAnimated } = require("./png");
10	const { artifactPath } = require("./artifacts-dir");
11	
12	/**
13	 * Compare a freshly rendered PNG buffer to the committed golden at
14	 * `expectedPath`. On any difference, writes `<name>.actual.png` and (when
15	 * dimensions allow) `<name>.diff.png` into the artifacts dir and returns a
16	 * failure description; returns { ok: true } on an exact match.
