 .plan-time { font-size: 0.74rem; font-weight: 700; color: var(--red-dark); }
 .plan-title { font-family: var(--serif); font-weight: 600; font-size: 1.06rem; line-height: 1.18; margin: 1px 0; }
 .plan-sub { font-size: 0.78rem; color: var(--muted); }
+/* A show named in the plan links to its own page on edfringe.com. The selected
+   show links from its title (the title IS the show, so it's where you'd click);
+   the commitment's title is a venue, so its show is named underneath instead. */
+.plan-title-link { color: inherit; text-decoration: none; }
+.plan-title-link:hover { text-decoration: underline; text-decoration-color: var(--blue); }
+.plan-title-out { font-size: 0.8rem; font-weight: 700; color: var(--blue); }
+.plan-dest-show { display: inline-block; margin-top: 4px; font-size: 0.78rem; font-weight: 700; color: var(--blue); text-decoration: none; }
+.plan-dest-show:hover { text-decoration: underline; }
+.plan-title-link:focus-visible, .plan-dest-show:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; border-radius: 6px; }
 .plan-slack { display: inline-block; font-size: 0.68rem; font-weight: 700; padding: 3px 9px; border-radius: 999px; }
 .plan-slack.ok { color: var(--ok-text); background: var(--ok-bg); }
 .plan-slack.late { color: var(--red-dark); background: #fde7e7; }
@@ -1384,6 +1393,12 @@ a { color: inherit; }
 .show-genre { align-self: flex-start; font-size: 0.62rem; text-transform: uppercase; letter-spacing: 0.05em; font-weight: 700; color: var(--red); margin: 0 0 2px; }
 .show-name { font-family: var(--serif); font-weight: 600; font-size: 1rem; margin: 0 0 2px; line-height: 1.15; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
 .show-meta { color: var(--muted); font-size: 0.78rem; margin: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
+/* The row's out-link to edfringe.com. Quiet, so it doesn't compete with the
+   row's own job (picking the show into the plan) — and clicking it only ever
+   opens the show's page, never changes the plan. */
+.si-link { align-self: flex-start; margin-top: 3px; font-size: 0.72rem; font-weight: 700; color: var(--blue); text-decoration: none; }
+.si-link:hover { text-decoration: underline; }
+.si-link:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; border-radius: 6px; }
 .si-side { flex: 0 0 auto; text-align: right; }
 .si-time { font-family: var(--serif); font-weight: 700; font-size: 1rem; color: var(--ink); }
 .si-walk { font-size: 0.72rem; color: var(--muted); }

