const {decode}=require("./product/requirements/shared/png.js");
const fs=require("fs");
const a=decode(fs.readFileSync("product/requirements/shared/.artifacts/now-chrome.1.3.actual.png"));
const b=decode(fs.readFileSync("product/requirements/screen/cases/now-chrome.1.3.png"));
let minx=1e9,maxx=-1,miny=1e9,maxy=-1,n=0;
for(let y=0;y<a.height;y++)for(let x=0;x<a.width;x++){const o=(y*a.width+x)*4;
 if(a.rgba[o]!==b.rgba[o]||a.rgba[o+1]!==b.rgba[o+1]||a.rgba[o+2]!==b.rgba[o+2]){n++;if(x<minx)minx=x;if(x>maxx)maxx=x;if(y<miny)miny=y;if(y>maxy)maxy=y;}}
console.log({n,minx,maxx,miny,maxy,w:a.width,h:a.height});
'

